// Context: When creating multiple parameter descriptors from a
// template, clone() produces an independent deep copy. Without
// it, all entries would share the same object reference and
// the last modification would overwrite all previous ones.

const var template = {
    "ID": "",
    "min": -100.0,
    "max": 0.0,
    "mode": "Decibel",
    "defaultValue": -100.0,
    "connections": [{ "processorId": "", "parameterId": "Gain" }]
};

const var params = [];

// Each clone is independent -- modifying one doesn't affect others
for(i = 0; i < 4; i++)
{
    var p = template.clone();
    var name = "Send " + (i + 1);
    p.ID = name;
    p.connections[0].processorId = name;
    params.push(p);
}

Console.print(params[0].ID);  // "Send 1"
Console.print(params[3].ID);  // "Send 4"

// Context: A plugin with multiple channel strips builds its full
// automation parameter list by creating sub-arrays per channel,
// then concatenating them into one master array. concat() modifies
// in-place -- there is no return value.

inline function makeChannelParams(channelIndex)
{
    local params = [];
    local ch = channelIndex + 1;

    params.push({
        "ID": "Volume " + ch,
        "min": -100.0,
        "max": 0.0,
        "connections": [{ "processorId": "Gain " + ch, "parameterId": "Gain" }]
    });

    params.push({
        "ID": "Pan " + ch,
        "min": -100.0,
        "max": 100.0,
        "connections": [{ "processorId": "Gain " + ch, "parameterId": "Balance" }]
    });

    return params;
}

// Accumulate all channel parameters into one list
const var NUM_CHANNELS = 4;
const var allParams = [];

for(i = 0; i < NUM_CHANNELS; i++)
    allParams.concat(makeChannelParams(i));

Console.print(allParams.length); // 8 (2 params x 4 channels)

var a = [2, 4, 6, 8];
Console.print(a.every(function(x){ return x % 2 == 0; }));
Console.print(a.every(function(x){ return x > 5; }));

// Context: A step sequencer reads a MidiPlayer's event list, then
// filters to find note-on events for a specific note within a
// time window. Each sequencer step queries its own time range.

const var mp = Synth.getMidiPlayer("Player1");
mp.setUseTimestampInTicks(true);

const var events = mp.getEventList();
const var ticksPerBar = mp.getTicksPerQuarter() * 4;

// Filter note-on events for a specific note within a time range
const var NOTE = 36;
const var noteOns = events.filter(function(e)
{
    return e.getTimestamp() < ticksPerBar &&
           e.isNoteOn() &&
           e.getNoteNumber() == NOTE;
});

Console.print("Found " + noteOns.length + " hits for note " + NOTE);

// Filter controller events by CC number
const var CHANCE_CC = 20;
const var chanceEvents = events.filter(function(e)
{
    return e.isController() &&
           e.getControllerNumber() == CHANCE_CC;
});

// Context: When the filter condition depends on a local variable,
// use the [capture] syntax to bring it into scope.

const var mp = Synth.getMidiPlayer("Player1");
const var events = mp.getEventList();

inline function getControllersForCC(list, ccNumber)
{
    return list.filter(function [ccNumber](e)
    {
        return e.isController() &&
               e.getControllerNumber() == ccNumber;
    });
}

const var modWheelEvents = getControllersForCC(events, 1);

// Context: A sequencer finds the note-off event that pairs with
// a specific note-on, using the event ID to match them.

const var mp = Synth.getMidiPlayer("Player1");
const var events = mp.getEventList();
const var noteOnId = 42;

const var matchingNoteOff = events.find(function(e)
{
    return e.getEventId() == noteOnId && e.isNoteOff();
});

if(isDefined(matchingNoteOff))
{
    local offTimestamp = matchingNoteOff.getTimestamp();
    Console.print("Note-off at tick " + offTimestamp);
}

