// Context: When removing elements during a forward loop, decrement
// the index after removal to avoid skipping the next element.

// Remove expired entries from a tracking stack
const var stack = [
    {"progress": 0.5},
    {"progress": 1.2},
    {"progress": 0.8},
    {"progress": 1.5},
    {"progress": 0.3}
];

for(i = 0; i < stack.length; i++)
{
    if(stack[i].progress > 1.0)
        stack.removeElement(i--);
}

Console.print(stack.length); // 3

// Context: A voice visualization keeps a fixed-size stack of active
// notes. When the stack is full, find the oldest entry and remove
// it by index before inserting the new one.

const var stack = [];
for(i = 0; i < 130; i++)
    stack.push({"elapsed": i});

const var MAX_VOICES = 128;

// Find the entry with the largest elapsed time (oldest)
if(stack.length >= MAX_VOICES)
{
    var maxIdx = 0;
    var maxValue = 0.0;
    var idx = 0;

    for(s in stack)
    {
        if(s.elapsed > maxValue)
        {
            maxIdx = idx;
            maxValue = s.elapsed;
        }

        idx++;
    }

    stack.removeElement(maxIdx);
}

Console.print(stack.length); // 129

// Context: Any array that will be modified in onNoteOn/onNoteOff
// must be pre-allocated in onInit. This prevents reallocation
// warnings and potential audio glitches.

// Simple flat array for tracking uptimes per note
const var uptimes = [];
uptimes.reserve(128);

for(i = 0; i < 128; i++)
    uptimes[i] = 0.0;

// Nested arrays: each sub-array needs its own reserve call
const var eventIds = [];
eventIds.reserve(128);

for(i = 0; i < 128; i++)
{
    eventIds[i] = [];
    eventIds[i].reserve(16);
}

// Now push/pop in MIDI callbacks stays within allocated capacity
function onNoteOn()
{
    eventIds[Message.getNoteNumber()].push(Message.getEventId());
    uptimes[Message.getNoteNumber()] = Engine.getUptime();
}

function onNoteOff()
{
    local note = Message.getNoteNumber();
    local ids = eventIds[note];

    // pop from pre-allocated array -- no reallocation
    if(!ids.isEmpty())
        ids.pop();
}

