description.userDocs:
The Builder constructs and configures the HISE module tree from script. It creates sound generators, effects, modulators, and MIDI processors programmatically, replacing manual point-and-click module setup in the IDE.

The Builder is a development-time tool for assembling repetitive or complex module trees. Typical use cases include:

1. Building N identical channel strips in a loop (container, synth, MIDI processors, effects)
2. Scaffolding a modulation matrix with per-oscillator modulator targets
3. Constructing master and send effect chains with per-channel send routing

Obtain a Builder instance with:

```javascript
const var b = Synth.createBuilder();
```

Every call to `create()` or `getExisting()` returns a **build index** - an integer that identifies the module within this Builder session. Index 0 is always the MainSynthChain. Pass build indexes to `get()`, `setAttributes()`, `clearChildren()`, and `connectToScript()` to operate on specific modules.

Module types are selected from dynamic constant objects on the Builder instance:

| Constant | Contents |
|----------|----------|
| `b.SoundGenerators` | All registered synth types |
| `b.Modulators` | All registered modulator types |
| `b.Effects` | All registered effect types |
| `b.MidiProcessors` | All registered MIDI processor types |
| `b.ChainIndexes` | Named chain slots: `Direct` (-1), `Midi` (0), `Gain` (1), `Pitch` (2), `FX` (3) |
| `b.InterfaceTypes` | Typed wrapper names for use with `get()` |

> Builder code is a development tool, not a runtime feature. The recommended workflow is: uncomment the build code, compile once to rebuild the module tree, then re-comment it. The module tree persists in the XML preset - there is no need to rebuild on every compile. Never ship Builder calls in a compiled plugin; they are deactivated in exported builds.

> All module creation is restricted to the `onInit` callback. Calling `create()` from any other callback will throw a script error.

## Conditional Compilation

Put all Builder code in a separate file and control execution by commenting or uncommenting the `include()` statement in your main script. This keeps the build logic isolated and avoids accidentally rebuilding the module tree on every compile:

```javascript
// Interface.js

// Uncomment to rebuild the module tree, then re-comment:
//include("Builder.js");

// ... rest of your interface code
```

Inside the Builder file, use boolean flags to control which sections get rebuilt. This lets you iterate on one part of the tree without tearing down everything:

```javascript
// Builder.js
const var b = Synth.createBuilder();

const var BUILD_CHANNELS = 1;
const var BUILD_MASTER_FX = 0;
const var BUILD_SENDS = 0;

b.clear();

if(BUILD_CHANNELS)
    buildChannels(b);

if(BUILD_MASTER_FX)
    buildMasterFX(b);

if(BUILD_SENDS)
    buildSendEffects(b);

b.flush();
```

The module tree persists in the XML preset, so the Builder only needs to run when you change the structure. Keeping it commented out by default also avoids the stability risks of clearing and recreating modules on every compile.

## Common Mistakes

- **Wrong:** `b.create(...); // no flush at the end`
  **Right:** `b.create(...); b.flush();`
  *Forgetting `flush()` leaves the patch browser and UI out of sync with the actual module tree. The Builder's destructor will log a warning if you forget.*

- **Wrong:** Running Builder code on every compile
  **Right:** Commenting out the build call (or its `include` statement) after use
  *Rebuilding the entire module tree on every compile is slow and unnecessary. The tree persists in the preset XML. Uncomment only when you need to modify the structure.*

- **Wrong:** Building N identical channels by hand in the IDE
  **Right:** Using a loop with indexed IDs (e.g. `"Sampler " + (i + 1)`)
  *Manual construction is error-prone for repetitive structures. A loop trivially creates N identical processor chains, and adding a new module to every channel becomes a one-line change.*

- **Wrong:** Creating all modules in one monolithic block
  **Right:** Splitting into per-section build functions with conditional flags
  *Boolean flags (`BUILD_CHANNELS`, `BUILD_MASTER_FX`, `BUILD_SENDS`) let you iterate on one section without rebuilding the entire tree.*

examples.code:
// Context: When rebuilding only part of the module tree (e.g. the gain
// modulators of an oscillator group), use clearChildren() to remove
// existing children from a specific chain without affecting the rest.

const var b = Synth.createBuilder();

inline function buildOscillator(index)
{
    local group = b.create(b.SoundGenerators.SynthGroup,
        "OSC" + index, 0, b.ChainIndexes.Direct);

    // Clear existing gain modulators before adding new ones
    b.clearChildren(group, b.ChainIndexes.Gain);

    local synth = b.create(b.SoundGenerators.WavetableSynth,
        "WT" + index, group, b.ChainIndexes.Direct);

    // Add MatrixModulators to the now-empty gain chain
    b.create(b.Modulators.MatrixModulator,
        "OSC" + index + " Gain", group, b.ChainIndexes.Gain);
    b.create(b.Modulators.MatrixModulator,
        "OSC" + index + " Pan", group, b.ChainIndexes.Gain);
}

b.clear();
buildOscillator(1);
b.flush();

Console.print(Synth.getChildSynth("OSC1").getId());
Console.print(Synth.getModulator("OSC1 Gain").getId());

// Context: When building N channels that each need a MIDI script processor
// (e.g. for arpeggio, loop control, or note processing), create a
// ScriptProcessor for each channel and connect it to a shared .js file.
// Each instance gets its own state but shares the same script logic.

const var NUM_CHANNELS = 4;
const var b = Synth.createBuilder();
b.clear();

for (i = 0; i < NUM_CHANNELS; i++)
{
    var container = b.create(b.SoundGenerators.SynthChain,
        "Container " + (i + 1), 0, b.ChainIndexes.Direct);
    var synth = b.create(b.SoundGenerators.SilentSynth,
        "Channel " + (i + 1), container, b.ChainIndexes.Direct);

    // Create a ScriptProcessor and connect it to the shared script
    var scriptProc = b.create(b.MidiProcessors.ScriptProcessor,
        "MidiScript " + (i + 1), synth, b.ChainIndexes.Midi);

    b.connectToScript(scriptProc,
        "{PROJECT_FOLDER}ConnectedScripts/ChannelProcessor.js");
}

b.flush();

// Context: Building N identical processing channels in a loop. Each channel
// gets a container synth, a sound generator, MIDI processors, and effects.
// This is the Builder's primary advantage over manual tree construction.

const var NUM_CHANNELS = 4;
const var b = Synth.createBuilder();

inline function buildChannel(channelIndex)
{
    // Container for this channel (Direct = add as sound generator)
    local container = b.create(b.SoundGenerators.SynthChain,
        "Container " + (channelIndex + 1), 0, b.ChainIndexes.Direct);

    // Sound generator inside the container
    local synth = b.create(b.SoundGenerators.SilentSynth,
        "Channel " + (channelIndex + 1), container, b.ChainIndexes.Direct);

    // MIDI processor on the synth
    local muter = b.create(b.MidiProcessors.MidiMuter,
        "Muter " + (channelIndex + 1), synth, b.ChainIndexes.Midi);

    // Effects on the container
    local eq = b.create(b.Effects.HardcodedMasterFX,
        "EQ " + (channelIndex + 1), container, b.ChainIndexes.FX);

    local gain = b.create(b.Effects.SimpleGain,
        "Gain " + (channelIndex + 1), container, b.ChainIndexes.FX);
}

b.clear();

for (i = 0; i < NUM_CHANNELS; i++)
    buildChannel(i);

b.flush();

// After building, retrieve modules by name:
Console.print(Synth.getChildSynth("Channel 1").getId());
Console.print(Synth.getEffect("Gain 1").getId());
Console.print(Synth.getChildSynth("Container 4").getId());

// Context: Large Builder scripts benefit from boolean flags that enable/disable
// subsections. This lets you iterate on one part of the tree without rebuilding
// everything, which speeds up development significantly.

const var BUILD_CHANNELS = 1;
const var BUILD_MASTER_FX = 1;
const var BUILD_SENDS = 0; // Disabled while working on channels

const var b = Synth.createBuilder();
b.clear();

if (BUILD_CHANNELS)
{
    for (i = 0; i < NUM_CHANNELS; i++)
        buildChannel(i);
}

if (BUILD_MASTER_FX)
{
    b.create(b.Effects.CurveEq, "MasterEQ", 0, b.ChainIndexes.FX);
    b.create(b.Effects.SimpleGain, "MasterGain", 0, b.ChainIndexes.FX);
}

if (BUILD_SENDS)
    buildSendEffects();

b.flush();

// Context: After creating processors with create(), use get() to obtain typed
// references for operations that need specific interfaces. The most common are
// RoutingMatrix (multi-channel routing), SlotFX (loading DSP networks), and
// Effect (bypass/attribute control).

const var b = Synth.createBuilder();
b.clear();

var container = b.create(b.SoundGenerators.SynthChain,
    "Channel 1", 0, b.ChainIndexes.Direct);
var synth = b.create(b.SoundGenerators.SilentSynth,
    "Synth 1", container, b.ChainIndexes.Direct);

// RoutingMatrix: configure multi-channel audio routing
var matrix = b.get(synth, b.InterfaceTypes.RoutingMatrix);
matrix.setNumChannels(6);
matrix.addConnection(2, 0);
matrix.addConnection(3, 1);

// SlotFX: load a compiled DSP network into a HardcodedFX
var fx = b.create(b.Effects.HardcodedMasterFX,
    "MyEffect", container, b.ChainIndexes.FX);
b.get(fx, b.InterfaceTypes.SlotFX).setEffect("my_dsp_network");

// Effect: control bypass state
b.get(fx, b.InterfaceTypes.Effect).setBypassed(true);

b.flush();

// Context: When building a modulation matrix, get() with InterfaceTypes.Modulator
// returns a reference that supports setMatrixProperties() for configuring the
// modulator's input/output ranges and text converter.

const var b = Synth.createBuilder();

var groupIdx = b.create(b.SoundGenerators.SynthGroup,
    "OSC1", 0, b.ChainIndexes.Direct);

// Create a MatrixModulator on the gain chain
var modIdx = b.create(b.Modulators.MatrixModulator,
    "OSC1 Gain", groupIdx, b.ChainIndexes.Gain);

// Get the Modulator interface to configure matrix properties
var mod = b.get(modIdx, b.InterfaceTypes.Modulator);
mod.setMatrixProperties({
    "InputRange": { "min": -100.0, "max": 6.0, "middlePosition": 0.0 },
    "OutputRange": { "min": 0.0, "max": 2.0 },
    "TextConverter": "Decibels"
});

b.flush();

Console.print(Synth.getChildSynth("OSC1").getId());
Console.print(Synth.getModulator("OSC1 Gain").getId());

// Context: When building in phases (channels first, then send effects),
// use getExisting() to look up modules created in an earlier pass. This is
// essential for send effect architectures where per-channel sends must
// reference a shared send bus created separately.

const var NUM_CHANNELS = 4;
const var b = Synth.createBuilder();
b.clear();

// Phase 1: Build channels
for (i = 0; i < NUM_CHANNELS; i++)
{
    b.create(b.SoundGenerators.SynthChain,
        "Container " + (i + 1), 0, b.ChainIndexes.Direct);
}

// Phase 2: Create shared send bus
var sendContainer = b.create(b.SoundGenerators.SendContainer,
    "SendFX", 0, b.ChainIndexes.Direct);
b.create(b.Effects.HardcodedMasterFX,
    "Delay", sendContainer, b.ChainIndexes.FX);
b.create(b.Effects.HardcodedMasterFX,
    "Reverb", sendContainer, b.ChainIndexes.FX);

// Phase 3: Add per-channel send effects by looking up existing containers
for (i = 0; i < NUM_CHANNELS; i++)
{
    var c = b.getExisting("Container " + (i + 1));

    b.create(b.Effects.SimpleGain,
        "ChannelGain " + (i + 1), c, b.ChainIndexes.FX);
    b.create(b.Effects.SendFX,
        "SendDelay " + (i + 1), c, b.ChainIndexes.FX);
    b.create(b.Effects.SendFX,
        "SendReverb " + (i + 1), c, b.ChainIndexes.FX);
}

b.flush();

Console.print(Synth.getChildSynth("Container 1").getId());
Console.print(Synth.getEffect("ChannelGain 1").getId());
Console.print(Synth.getChildSynth("SendFX").getId());

// Add the AHDSR (we need to save the return value for the next call)
var ahdsr = builder.create(builder.Modulators.AHDSR,    // the module type
	               "GainAHDSR " + (i+1),        // the ID 
	               sampler,                     // the parent module
	               builder.ChainIndexes.Gain);  // the slot type


builder.setAttributes(ahdsr, {
  "Attack": 8000,
  "Release": 100.0
});

