// Context: The idiomatic hover pattern used throughout professional HISE
// plugins. Multiplying a 0/1 hover flag by a constant blend factor
// avoids branching and keeps highlight intensity consistent across
// all controls.

const var HOVER_ALPHA = 0.25;

const var laf = Content.createLocalLookAndFeel();

laf.registerFunction("drawRotarySlider", function(g, obj)
{
    // obj.hover is 0.0 or 1.0 -- multiplying by HOVER_ALPHA produces
    // 0.0 (no change) or 0.25 (subtle white blend)
    var c = Colours.mix(obj.itemColour1, Colours.white, obj.hover * HOVER_ALPHA);
    g.setColour(c);
    g.fillEllipse(Rect.reduced(obj.area, 4.0));
});

// Context: Using a normalized 0.0-1.0 value as the blend factor to
// smoothly transition between an inactive and active colour.

const var panel = Content.addPanel("ModIndicator", 10, 10);
panel.set("width", 20);
panel.set("height", 20);

panel.setPaintRoutine(function(g)
{
    // Blend from dark grey to bright yellow based on modulation depth
    var c = Colours.mix(0xFF404040, 0xFFFFF600, this.data.value);
    g.setColour(c);
    g.fillEllipse(this.getLocalBounds(2));
});

// Context: When using ScriptShader for GPU-rendered visuals, shader
// uniforms expect float arrays. toVec4 converts an ARGB integer
// colour into the [r, g, b, a] float format that GLSL vec4 requires.

const var panel = Content.addPanel("ShaderPanel", 0, 0);
panel.set("width", 400);
panel.set("height", 400);

const var shader = Content.createShader("myShader");

// Convert a theme colour and pass it to the shader
var accentColour = Colours.withAlpha(0xFF94F2FF, 0.8);
shader.setUniformData("uColour", Colours.toVec4(accentColour));

// The shader receives it as: uniform vec4 uColour; // [r, g, b, a] in 0.0-1.0

// Context: toVec4 is useful for debugging or computing with individual
// colour channels as normalized floats.

var rgba = Colours.toVec4(Colours.dodgerblue);

Console.print("R: " + rgba[0]); // R: 0.118 (approx)
Console.print("G: " + rgba[1]); // G: 0.565 (approx)
Console.print("B: " + rgba[2]); // B: 1.0
Console.print("A: " + rgba[3]); // A: 1.0

// Context: The dominant use case -- deriving transparent variants of
// a centralized theme colour inside look-and-feel paint callbacks.

const var ACCENT_COLOUR = 0xFFC9EAF1;
const var PASSIVE_ALPHA = 0.4;

const var laf = Content.createLocalLookAndFeel();

laf.registerFunction("drawRotarySlider", function(g, obj)
{
    // Dashed arc outline at passive transparency
    g.setColour(Colours.withAlpha(ACCENT_COLOUR, PASSIVE_ALPHA));
    g.drawEllipse(Rect.reduced(obj.area, 2.0), 1.0);

    // Value arc at full opacity on hover, dimmed otherwise
    g.setColour(Colours.withAlpha(ACCENT_COLOUR, obj.hover ? 0.9 : 0.6));
    g.fillEllipse(Rect.reduced(obj.area, 8.0));

    // Glow effect using the theme colour at low alpha
    g.addDropShadowFromAlpha(Colours.withAlpha(ACCENT_COLOUR, 0.8), 4);
});

// Context: The most common withAlpha pattern -- choosing transparency
// based on obj.hover or obj.over in LAF and ScriptPanel paint routines.

const var knob = Content.addKnob("MyKnob", 10, 10);

const var laf = Content.createLocalLookAndFeel();

laf.registerFunction("drawToggleButton", function(g, obj)
{
    // Higher alpha on hover, lower when idle
    var c = Colours.withAlpha(Colours.white, obj.over ? 0.8 : 0.4);
    g.setColour(c);
    g.fillRoundedRectangle(obj.area, 3.0);
});

knob.setLocalLookAndFeel(laf);

// Context: Assigning distinct colours to items in a list (channels,
// categories, notes) by distributing hue values evenly around the
// colour wheel. Start from any base colour -- only its saturation
// and brightness are preserved; the hue is replaced.

const var NUM_ITEMS = 8;

// Generate a palette of 8 evenly-spaced hues
for (i = 0; i < NUM_ITEMS; i++)
{
    var c = Colours.withHue(Colours.red, i / NUM_ITEMS);
    c = Colours.withSaturation(c, 0.5);
    c = Colours.withBrightness(c, 0.4);
    Console.print("Item " + i + ": " + c);
}

// Context: Creating randomized colours for visual variety (e.g., preset
// tags, user categories) while keeping them visually cohesive by fixing
// saturation and brightness.

inline function getRandomColour()
{
    local c = Colours.withHue(Colours.red, Math.random());
    c = Colours.withSaturation(c, 0.5);
    c = Colours.withBrightness(c, 0.4);
    return c;
}

var c1 = getRandomColour();
var c2 = getRandomColour();
Console.print("Colour 1: " + c1);
Console.print("Colour 2: " + c2);

// Context: Level meters and status LEDs typically need a dim "off" state
// and a bright "on" state derived from the same base colour. Computing
// these once at init and storing as const var avoids per-frame
// Colours method calls during paint.

const var LED_BASE = 0xFF5B6870;
const var LED_OFF  = Colours.withMultipliedBrightness(LED_BASE, 0.1);
const var LED_ON   = Colours.withMultipliedBrightness(LED_BASE, 1.5);

Console.print(LED_OFF);  // very dark variant
Console.print(LED_ON);   // boosted brightness (clamped internally)

// Context: An alternative hover technique to Colours.mix -- multiply
// brightness above 1.0 when hovered to brighten the colour in-place.
// Works well for saturated accent colours where mixing with white
// would desaturate.

const var laf = Content.createLocalLookAndFeel();

laf.registerFunction("drawRotarySlider", function(g, obj)
{
    // Factor > 1.0 brightens on hover; 1.0 leaves unchanged
    var c = Colours.withMultipliedBrightness(obj.itemColour1, obj.hover ? 1.4 : 1.0);
    g.setColour(c);
    g.fillEllipse(Rect.reduced(obj.area, 4.0));
});

// Context: Desaturating a knob's colour when its value is low and
// fully saturating it at maximum. This creates a visual link between
// the parameter value and the colour intensity. The factor is the
// normalized knob value (0.0-1.0), clamped to a minimum so the
// colour never goes fully grey.

const var laf = Content.createLocalLookAndFeel();

laf.registerFunction("drawRotarySlider", function(g, obj)
{
    // Clamp to 0.2 minimum so the arc is always slightly coloured
    var c = Colours.withMultipliedSaturation(obj.itemColour1, Math.max(0.2, obj.valueNormalized));
    g.setColour(c);
    g.drawEllipse(Rect.reduced(obj.area, 4.0), 2.0);
});

