// Context: An FX lock feature saves the Base64 state of master/send effects
// before a preset loads, then restores them after.

const var masterFX = [Synth.getEffect("MasterEQ"),
                      Synth.getEffect("MasterComp"),
                      Synth.getEffect("MasterLimiter")];

const var sendFX = [Synth.getEffect("Delay"),
                    Synth.getEffect("ReverbA"),
                    Synth.getEffect("ReverbB")];

// Organized as two lockable groups
const var fxGroups = [masterFX, sendFX];
const var savedStates = [[], []];
const var lockEnabled = [false, false];

// Called before preset load (e.g., from a UserPresetHandler pre-load callback)
inline function saveFxStates()
{
    for (i = 0; i < fxGroups.length; i++)
    {
        if (!lockEnabled[i])
            continue;

        savedStates[i] = [];

        for (fx in fxGroups[i])
            savedStates[i].push(fx.exportState());
    }
}

// Called after preset load
inline function restoreFxStates()
{
    for (i = 0; i < fxGroups.length; i++)
    {
        if (!lockEnabled[i])
            continue;

        for (j = 0; j < fxGroups[i].length; j++)
        {
            if (savedStates[i][j].length > 0)
                fxGroups[i][j].restoreState(savedStates[i][j]);
        }
    }
}

// Context: Export all effects in a group as a JSON file keyed by effect ID,
// allowing users to save and recall custom FX setups.

const var fxList = [Synth.getEffect("MasterEQ"),
                    Synth.getEffect("MasterComp"),
                    Synth.getEffect("MasterLimiter")];

// Save: serialize each effect's state into a JSON object
inline function saveFxToFile(file)
{
    local content = {};

    for (fx in fxList)
        content[fx.getId()] = fx.exportState();

    file.writeObject(content);
}

// Load: restore each effect from the JSON object
inline function loadFxFromFile(file)
{
    local content = file.loadAsObject();

    for (fx in fxList)
    {
        local state = content[fx.getId()];

        if (isDefined(state))
            fx.restoreState(state);
    }
}

// Context: A ScriptPanel-based peak meter polls effect output levels
// in a timer callback and renders smoothed bars with peak indicators.

const var gainFx = Synth.getEffect("OutputGain");
const var meterPanel = Content.addPanel("PeakMeter", 0, 0);

const var DECAY = 0.77;
const var PEAK_HOLD_FRAMES = 30;

meterPanel.data.left = 0.0;
meterPanel.data.right = 0.0;
meterPanel.data.leftMax = 0.0;
meterPanel.data.rightMax = 0.0;
meterPanel.data.leftMaxCounter = 0;
meterPanel.data.rightMaxCounter = 0;

meterPanel.setTimerCallback(function()
{
    // Poll left and right output levels, clamped to [0, 1]
    local l = Math.min(1.0, gainFx.getCurrentLevel(true));
    local r = Math.min(1.0, gainFx.getCurrentLevel(false));

    // Smoothed attack/decay: fast attack, slow decay
    if (l > this.data.left)
        this.data.left = this.data.left * 0.3 + 0.7 * l;
    else
        this.data.left *= DECAY;

    if (r > this.data.right)
        this.data.right = r;
    else
        this.data.right *= DECAY;

    // Peak hold: remember the max value and hold for N frames
    if (l > this.data.leftMax)
    {
        this.data.leftMax = l;
        this.data.leftMaxCounter = PEAK_HOLD_FRAMES;
    }

    if (--this.data.leftMaxCounter <= 0)
        this.data.leftMax = 0.0;

    this.repaint();
});

meterPanel.startTimer(30);

// Context: A configurable meter that can show either a specific effect's
// output or the master output, depending on whether an effect is assigned.

const var meters = [];

// Each meter can optionally be assigned to a specific effect
inline function refreshMeter(panel)
{
    local l = isDefined(panel.data.fx)
        ? panel.data.fx.getCurrentLevel(true)
        : Engine.getMasterPeakLevel(0);

    local r = isDefined(panel.data.fx)
        ? panel.data.fx.getCurrentLevel(false)
        : Engine.getMasterPeakLevel(1);

    // Apply power curve for perceptual scaling
    l = Math.pow(l / 2.0, 0.25);
    r = Math.pow(r / 2.0, 0.25);

    panel.data.left = l;
    panel.data.right = r;
    panel.repaint();
}

// Context: A dynamics display panel uses isSuspended() to avoid showing
// stale gain reduction and peak values when no audio flows through the effect.

const var compressor = Synth.getEffect("MasterComp");
const var compPanel = Content.getComponent("CompressorPanel");

compPanel.setTimerCallback(function()
{
    local peak = this.data.peakBuffer.getMagnitude(
        this.data.peakBuffer.length - 1024, 1024);
    local gainReduction = this.data.grBuffer.getMagnitude(
        this.data.grBuffer.length - 1024, 1024);

    // When the compressor is suspended (no audio flowing),
    // zero out the display to avoid frozen stale values
    if (compressor.isSuspended())
    {
        gainReduction = 0.0;
        peak = 0.0;
    }

    this.data.peak = peak;
    this.data.gainReduction = 1.0 - Math.pow(gainReduction, 1.0);
    this.repaint();
});

