createBroadcaster.userDocs:
Creates a broadcaster for sending messages to attached listeners. Pass a JSON object with `id` and `args` properties to define the broadcaster's identity and argument schema. The `args` property can be an array of argument name strings or a JSON object mapping names to default values. The argument count determines which `attach*` source methods are compatible.

```js
const var bc = Engine.createBroadcaster({
    "id": "MyBroadcaster",
    "args": ["value", "source"]
});
```

examples.code:
// Context: Performance-critical systems (grain engines, resonance
// models) combine fixed-layout objects for typed per-element data
// with an unordered stack for tracking active notes. This avoids
// heap allocation on the audio thread.

const var factory = Engine.createFixObjectFactory({
    "x": 0,
    "y": 0.0,
    "seed": 0.0,
    "gain": 1.0
});

// Pre-allocate a fixed array of grain descriptors
const var grains = factory.createArray(128);

// Track active notes without allocation
const var activeNotes = Engine.createUnorderedStack();

inline function onNoteOn()
{
    activeNotes.insert(Message.getNoteNumber());
}

inline function onNoteOff()
{
    activeNotes.remove(Message.getNoteNumber());
}

// Spawn a new grain using a random active note
inline function spawnGrain(obj)
{
    local numActive = activeNotes.size();

    if (numActive > 0)
    {
        obj.x = activeNotes[Math.randInt(0, numActive)];
        obj.y = Math.pow(Math.random(), 2.0) * 2.0;
        obj.seed = Math.random();
        obj.gain = Math.pow(1.0 - (obj.y * 0.5), 2.0);
    }
}

createFixObjectFactory.userDocs:
Creates a factory for fixed-layout objects with typed fields. Pass a JSON object where property names become field names and values define the type: integers for Integer fields, floats for Float fields, booleans for Boolean fields, or arrays of those for array-typed fields. These objects are more performant than regular JSON objects for large collections because they use contiguous memory with known offsets.

```js
var factory = Engine.createFixObjectFactory({
    "x": 0, "y": 0.0, "active": false
});
```

