// Context: When using a custom preset model, clear macro state at
// startup so the preset loader starts from a known empty state

const var mh = Engine.createMacroHandler();
mh.setExclusiveMode(true);

// Clear all macro connections - the update callback fires once after this
mh.setMacroDataFromObject([]);

var data = mh.getMacroDataObject();

// Context: Connect macro slots to custom automation parameters defined
// through UserPresetHandler.setCustomAutomation()

const var uph = Engine.createUserPresetHandler();
const var mh = Engine.createMacroHandler();
mh.setExclusiveMode(true);

// Custom automation requires the custom user preset model
uph.setUseCustomUserPresetModel(function(obj){}, function(){ return {}; }, false);

// Custom automation must be set up before macro connections reference it
uph.setCustomAutomation([
    {"ID": "ParamX", "min": 0.0, "max": 1.0, "defaultValue": 0.5, "connections": []},
    {"ID": "ParamY", "min": 0.0, "max": 1.0, "defaultValue": 0.5, "connections": []}
]);

// Connect macro 0 -> ParamX, macro 1 -> ParamY
mh.setMacroDataFromObject([
    {
        "MacroIndex": 0,
        "Processor": "Interface",
        "Attribute": "ParamX",
        "CustomAutomation": true,
        "FullStart": 0.0,
        "FullEnd": 1.0,
        "Start": 0.0,
        "End": 1.0,
        "Inverted": false,
        "Interval": 0.0,
        "Skew": 1.0
    },
    {
        "MacroIndex": 1,
        "Processor": "Interface",
        "Attribute": "ParamY",
        "CustomAutomation": true,
        "FullStart": 0.0,
        "FullEnd": 1.0,
        "Start": 0.0,
        "End": 1.0,
        "Inverted": false,
        "Interval": 0.0,
        "Skew": 1.0
    }
]);

var result = mh.getMacroDataObject();

// Context: Instead of a plain function, pass a Broadcaster to fan out
// macro change notifications to multiple independent listeners

const var mh = Engine.createMacroHandler();

// Create a broadcaster that will receive macro change events
const var macroBroadcaster = Engine.createBroadcaster({
    "id": "macroBroadcaster",
    "args": ["macroData"]
});

// The broadcaster itself becomes the callback - when macro connections
// change, it fires as a broadcaster message that any number of listeners
// can subscribe to
mh.setUpdateCallback(macroBroadcaster);

var listenerCount = 0;

// Now multiple independent listeners can react to macro changes
macroBroadcaster.addListener("", "update macro indicators", function(macroData)
{
    // Update UI indicators showing which macros are connected
    listenerCount++;
    Console.print("Active connections: " + macroData.length);
});

macroBroadcaster.addListener("", "sync context menu state", function(macroData)
{
    // Update context menu enabled/checked states
    for (item in macroData)
        Console.print("Slot " + item.MacroIndex + ": " + item.Attribute);
});

