}

// Context: Mapping a 0-1 slider to a logarithmic dB threshold
// requires a steep power curve. Using pow(x, 4.0) for the forward
// mapping and pow(x, 0.25) for the inverse keeps the conversions
// symmetrical.

inline function sliderToThreshold(value)
{
    local s = 1.0 - value;
    s = Math.pow(s, 4.0);
    s *= 0.999;
    s += 0.001;
    return Engine.getDecibelsForGainFactor(s);
}

inline function thresholdToSlider(dB)
{
    if (dB < -60.0)
        return 1.0;

    local s = Engine.getGainFactorForDecibels(dB);
    s -= 0.001;
    s /= 0.999;
    s = Math.pow(s, 0.25);  // Inverse of the forward curve
    return 1.0 - s;
}

// Round-trip test: slider -> dB -> slider should return the original value
var threshold = sliderToThreshold(0.7);
var roundTrip = thresholdToSlider(threshold);
Console.print(threshold);
Console.print(roundTrip);

// Context: Selecting a random preset from a list while avoiding
// the currently loaded preset requires a retry loop.

const var presets = ["Warm Pad", "Bright Lead", "Deep Bass", "Soft Keys"];
var lastPresetIndex = -1;

inline function loadRandomPreset()
{
    local index = Math.randInt(0, presets.length);

    // Retry until we get a different preset (up to 10 attempts)
    local attempts = 0;
    while (index == lastPresetIndex && attempts < 10)
    {
        index = Math.randInt(0, presets.length);
        attempts++;
    }

    lastPresetIndex = index;
    return presets[index];
}

var result = loadRandomPreset();
Console.print(result);

// Context: A "randomize" button picks random source and destination
// indices for modulation routing slots.

const var NUM_SOURCES = 8;
const var NUM_DESTINATIONS = 16;

inline function randomizeSlot()
{
    // Upper bound is exclusive: randInt(0, 8) returns 0-7
    local source = Math.randInt(0, NUM_SOURCES);
    local dest = Math.randInt(0, NUM_DESTINATIONS);
    return [source, dest];
}

var slot = randomizeSlot();
Console.print(slot[0] + ", " + slot[1]);

// Context: Randomizing a parameter value by a controlled amount
// requires converting the unipolar [0, 1) output to a bipolar
// [-1, 1) range, scaling by the randomization amount, then
// clamping back to valid bounds.

inline function randomizeValue(currentValue, amount)
{
    // Scale Math.random() from [0, 1) to [-1, 1) for bipolar offset
    local offset = amount * (2.0 * Math.random() - 1.0);
    return Math.range(currentValue + offset, 0.0, 1.0);
}

var currentX = 0.5;
var currentY = 0.5;

