// Context: Drum sequencers generate perfectly quantized notes. Adding
// a small random delay to artificial (sequencer) events creates a
// more human feel without affecting live MIDI input.

const var slopKnob = Content.addKnob("SlopAmount", 10, 10);
slopKnob.setRange(0, 1, 0.01);

const var MAX_DELAY_SEC = 0.05; // 50ms maximum slop

function onNoteOn()
{
    if (Message.isArtificial() && slopKnob.getValue() > 0)
    {
        // Skewed random: Math.pow with exponent > 1 biases toward shorter delays
        local delaySamples = parseInt(slopKnob.getValue() *
            Engine.getSampleRate() * MAX_DELAY_SEC *
            Math.pow(Math.random(), 1.5));

        Message.delayEvent(delaySamples);
    }
}

// Context: When remapping notes to different pitches using pitch bend,
// the controller message must be processed before the note. Delaying
// the note by 1 sample guarantees ordering within the same buffer.

function onNoteOn()
{
    local noteNumber = Message.getNoteNumber();

    // Remap notes in range 60-84 using pitch bend for continuous tuning
    if (noteNumber >= 60 && noteNumber <= 84)
    {
        local semitones = noteNumber - 72;
        local pitchValue = Math.min(16383, 8192 + parseInt(semitones / 12.0 * 8192));

        // Send pitch bend first
        Synth.sendController(Message.PITCH_BEND_CC, pitchValue);

        // Delay note by 1 sample so pitch bend arrives first
        Message.delayEvent(1);
        Message.setTransposeAmount(-(noteNumber - 36));
    }
}

// Context: The onController callback receives CC, pitch bend, aftertouch,
// and program change events. Use getControllerNumber() with the virtual
// CC constants to handle them uniformly.

function onController()
{
    local cc = Message.getControllerNumber();
    local val = Message.getControllerValue();

    if (cc == 64)
    {
        // Sustain pedal
        local pedalDown = val > 64;
        // ... handle sustain logic
    }
    else if (cc == 1)
    {
        // Mod wheel -> vibrato depth
        Synth.getModulator("Vibrato").setIntensity(val / 127.0);
    }
    else if (cc == Message.PITCH_BEND_CC) // 128
    {
        // Pitch wheel: val is 0-16383 (14-bit), not 0-127
        local normalized = (val - 8192) / 8192.0; // -1.0 to +1.0
        // ... apply pitch bend
    }
    else if (cc == Message.AFTERTOUC_CC) // 129
    {
        // Channel aftertouch: val is 0-127
        // ... apply aftertouch modulation
    }
    else if (Message.isProgramChange())
    {
        // Program change events also route through onController
        local pgm = Message.getProgramChangeNumber();
        // ... switch preset
    }
}

// Context: CC64 (sustain pedal) is the most commonly handled controller.
// Values above 64 mean "pedal down" per MIDI convention.

reg pedalDown = false;

function onController()
{
    if (Message.getControllerNumber() == 64)
    {
        local wasDown = pedalDown;
        pedalDown = Message.getControllerValue() > 64;

        if (wasDown && !pedalDown)
        {
            // Pedal released -- trigger release samples for held notes
        }
    }
}

// Context: An internal CC (sent from a sequencer grid) controls the
// probability of muting the next note. The controller value is
// normalized to 0.0-1.0 and compared against a random threshold.

reg muteNextNote = false;

function onController()
{
    if (Message.getControllerNumber() == 99)
    {
        // Normalize CC value (0-127) to probability
        local probability = Message.getControllerValue() / 127.0;
        muteNextNote = probability > Math.random();
    }
}

function onNoteOn()
{
    if (muteNextNote)
    {
        Message.ignoreEvent(true);
        muteNextNote = false;
    }
}

// Context: Sampler instruments use low notes as keyswitches to select
// articulations. The keyswitch note is consumed (ignored) and triggers
// a MidiMuter bypass change instead of producing sound.

const var KEYSWITCH_LOW = 24;  // C1
const var KEYSWITCH_HIGH = 35; // B1

const var muters = [Synth.getMidiProcessor("SusMuter"),
                    Synth.getMidiProcessor("StacMuter"),
                    Synth.getMidiProcessor("TremMuter")];

function onNoteOn()
{
    local n = Message.getNoteNumber();

    if (n >= KEYSWITCH_LOW && n <= KEYSWITCH_HIGH)
    {
        Message.ignoreEvent(true);

        local artIndex = n - KEYSWITCH_LOW;

        // Enable one articulation, mute all others
        for (i = 0; i < muters.length; i++)
            muters[i].setAttribute(0, i == artIndex ? 0 : 1);
    }
}

// Context: A MIDI processor that only passes through a single note number,
// ignoring everything else. Useful for isolating individual drum pads
// in a multi-pad instrument.

const var noteFilter = Content.addKnob("TargetNote", 0, 0);
noteFilter.setRange(0, 127, 1);

function onNoteOn()
{
    // ignoreEvent accepts a boolean-like argument:
    // true = ignore, false = allow through
    Message.ignoreEvent(Message.getNoteNumber() != noteFilter.getValue());
}

function onNoteOff()
{
    Message.ignoreEvent(Message.getNoteNumber() != noteFilter.getValue());
}

// Context: Suppress the original note and create a new artificial one
// so the script has full control over voice management and glide.

reg lastEventId = -1;
reg lastNote = -1;

const var glideKnob = Content.addKnob("Glide", 10, 10);
glideKnob.setRange(0, 1, 0.01);

function onNoteOn()
{
    Message.ignoreEvent(true);

    local newId = Synth.addNoteOn(Message.getChannel(),
                                   Message.getNoteNumber(),
                                   Message.getVelocity(), 0);

    if (lastNote != -1)
    {
        Synth.noteOffByEventId(lastEventId);

        // Glide from previous note
        local delta = (Message.getNoteNumber() - lastNote) *
                      Math.min(1.0, glideKnob.getValue());

        Synth.addPitchFade(newId, 0, -delta, 0);
        Synth.addPitchFade(newId, parseInt(glideKnob.getValue() * 1024), 0, 0);
    }

    lastEventId = newId;
    lastNote = Message.getNoteNumber();
}

function onNoteOff()
{
    if (Message.getNoteNumber() == lastNote)
    {
        Message.ignoreEvent(true);
        Synth.noteOffByEventId(lastEventId);
        lastNote = -1;
    }
}

// Context: A loop processor applies random timing slop to sequencer hits
// but leaves live MIDI input unmodified. Sequencer-generated notes
// (from Synth.addNoteOn or MidiPlayer) are flagged as artificial.

const var slopAmount = Content.addKnob("SlopAmount", 10, 10);
slopAmount.setRange(0, 1, 0.01);

const var slopEnabled = Content.addButton("EnableSlop", 10, 50);

const var MAX_DELAY_SEC = 0.05;

function onNoteOn()
{
    // Only humanize artificial (sequencer/arpeggiator) notes
    if (Message.isArtificial() && slopEnabled.getValue())
    {
        local maxSamples = Engine.getSampleRate() * MAX_DELAY_SEC;
        local delay = parseInt(slopAmount.getValue() * maxSamples * Math.random());
        Message.delayEvent(delay);
    }
}

// Context: A monophonic script needs stable event IDs to target
// specific voices for volume/pitch fades. makeArtificial() converts
// the incoming event and returns its event ID.

reg lastEventId = -1;
reg lastNote = -1;

function onNoteOn()
{
    local id = Message.makeArtificial();

    if (lastEventId != -1)
    {
        // Fade out the previous note before starting the new one
        Synth.addVolumeFade(lastEventId, 100, -100);
    }

    lastEventId = id;
    lastNote = Message.getNoteNumber();
}

function onNoteOff()
{
    if (Message.getNoteNumber() == lastNote)
    {
        lastEventId = -1;
        lastNote = -1;
    }
}

// Context: A polyphonic portamento script stores the artificial event ID
// per note number so each voice can be independently pitch-faded.

reg noteIds = [];
noteIds.reserve(128);

for (i = 0; i < 128; i++)
    noteIds.push(-1);

reg lastPlayedNote = -1;

const var glideTime = Content.addKnob("GlideTime", 10, 10);
glideTime.setRange(0, 500, 1);

function onNoteOn()
{
    local note = Message.getNoteNumber();

    // makeArtificial is idempotent: if called twice on the same event,
    // the second call returns the existing ID without creating a duplicate
    noteIds[note] = Message.makeArtificial();

    if (lastPlayedNote != -1 && lastPlayedNote != note)
    {
        local interval = note - lastPlayedNote;
        Synth.addPitchFade(noteIds[note], 0, -interval, 0);
        Synth.addPitchFade(noteIds[note], parseInt(glideTime.getValue()), 0, 0);
    }

    lastPlayedNote = note;
}

// Context: A release sample player tracks held notes using an
// UnorderedStack. When the host sends an all-notes-off message,
// the callback clears the tracking data to prevent stuck notes
// or orphaned release triggers.

const var stack = Engine.createUnorderedStack();
stack.setIsEventStack(true, stack.EventId);

reg pedalDown = false;

const var uptimes = [];
uptimes.reserve(128);

for (i = 0; i < 128; i++)
    uptimes[i] = 0.0;

// The callback runs on the audio thread -- must be an inline function
inline function onAllOff()
{
    stack.clear();
    pedalDown = false;

    for (i = 0; i < 128; i++)
        uptimes[i] = 0.0;
}

Message.setAllNotesOffCallback(onAllOff);

// Context: When a sampler has limited samples in the upper register,
// multiple notes can share the same sample with slight per-note detuning
// to avoid the "machine gun" effect. A deterministic pseudo-random table
// ensures consistent results across plays.

const var SHARED_RANGE_LOW = 50;
const var SHARED_RANGE_HIGH = 90;

// Build a deterministic pseudo-random detune table
const var detuneTable = [];

for (i = 0; i < 128; i++)
    detuneTable.push(parseInt(Math.sin(i * 925512.2934) * 100.0));

function onNoteOn()
{
    local note = Message.getNoteNumber();

    if (note >= SHARED_RANGE_LOW && note <= SHARED_RANGE_HIGH)
    {
        // Map multiple notes to the same sample via transpose
        local sampleNote = SHARED_RANGE_LOW + (note - SHARED_RANGE_LOW) % 2;

        Message.setTransposeAmount(sampleNote - note);

        // Add pseudo-random fine detuning for natural variation
        Message.setFineDetune(detuneTable[note]);
    }
}

// Context: An additive synthesis instrument uses setStartOffset to start
// each harmonic oscillator at a different phase position per note,
// creating organic key-click and attack variation. The phase angle
// is converted from radians to a sample offset within a single
// wavetable cycle.

const var CYCLE_LENGTH = 2048; // Samples per wavetable cycle

// Pre-computed phase offsets per MIDI note (radians)
const var phaseTable = [];

for (i = 0; i < 128; i++)
    phaseTable.push(Math.sin(i * 1.7) * Math.PI); // Pseudo-random distribution

function onNoteOn()
{
    local note = Message.getNoteNumber();

    // Convert phase angle (radians) to sample offset within one cycle
    local phaseDeg = Math.toDegrees(phaseTable[note] + (2 * Math.PI));
    local offset = parseInt(phaseDeg / 360 * CYCLE_LENGTH);

    Message.setStartOffset(offset);
}

// Context: In a sampled instrument, shifting which sample is triggered
// changes the timbre (brighter/darker) without changing the heard pitch.
// setTransposeAmount selects a different sample zone, while setCoarseDetune
// with the opposite sign cancels the pitch change.

const var timbreKnob = Content.addKnob("Timbre", 10, 10);
timbreKnob.setRange(-12, 12, 1);

function onNoteOn()
{
    local amount = parseInt(timbreKnob.getValue());

    // Transpose selects a different sample zone
    Message.setTransposeAmount(-amount);

    // Coarse detune cancels the pitch shift so the note sounds at the original pitch
    Message.setCoarseDetune(amount);
}

// Context: A piano plugin shifts timbre by a variable amount, clamping
// to the instrument's sample range so extreme values don't go out of bounds.

const var timbreKnob = Content.addKnob("Timbre", 10, 10);
timbreKnob.setRange(0, 4, 1);

const var NOTE_LOW = 21;   // Lowest sampled note (A0)
const var NOTE_HIGH = 108; // Highest sampled note (C8)

function onNoteOn()
{
    local amount = parseInt(timbreKnob.getValue()) * 2;

    // Clamp so the transposed note stays within the sample range
    local targetNote = Math.range(Message.getNoteNumber() - amount, NOTE_LOW, NOTE_HIGH);
    local actualShift = Message.getNoteNumber() - targetNote;

    Message.setTransposeAmount(-actualShift);
    Message.setCoarseDetune(actualShift);
}

// Context: A velocity table modifies the incoming velocity to match
// the instrument's dynamic response. The table provides a normalized
// curve (0.0-1.0 input/output) that reshapes the velocity distribution.

const var veloTable = Content.addTable("VeloTable", 10, 10);
veloTable.set("height", 200);
veloTable.set("width", 400);

const var table = veloTable.registerAtParent(0);

function onNoteOn()
{
    // Map velocity through the table curve
    local v = 127.0 * table.getTableValueNormalised(Message.getVelocity() / 127.0);

    Message.setVelocity(parseInt(Math.max(1, v)));
}

// Context: A sampler that plays release samples when notes are released.
// store() copies the note-on event into a MessageHolder for later replay
// as a release trigger. An UnorderedStack tracks all held notes.

const var holder = Engine.createMessageHolder();
const var stack = Engine.createUnorderedStack();
stack.setIsEventStack(true, stack.EventId);

const var uptimes = [];
uptimes.reserve(128);

for (i = 0; i < 128; i++)
    uptimes[i] = 0.0;

// Register a callback to clear state when all notes are released
inline function onAllOff()
{
    stack.clear();

    for (i = 0; i < 128; i++)
        uptimes[i] = 0.0;
}

Message.setAllNotesOffCallback(onAllOff);

inline function handleNoteOn()
{
    // Store the current event for later release triggering
    Message.store(holder);
    stack.insert(holder);
    uptimes[Message.getNoteNumber()] = Engine.getUptime();

    // Suppress the note-on from this sampler (it plays release samples only)
    Message.ignoreEvent(true);
}

inline function handleNoteOff()
{
    Message.store(holder);
    stack.removeIfEqual(holder);

    // Calculate note duration to choose short vs long release sample
    local duration = Engine.getUptime() - uptimes[holder.getNoteNumber()];
    local useShort = duration < 0.8;

    Sampler.setActiveGroup(useShort ? 1 : 2);
    holder.setGain(-6);

    // Replay the stored event as a release trigger
    Synth.addMessageFromHolder(holder);
}

const var mh = Engine.createMessageHolder();
mh.setType(mh.NoteOn);
mh.setNoteNumber(60);
mh.setVelocity(100);
mh.setChannel(1);

var copy = mh.clone();
copy.setNoteNumber(72);

Console.print(mh.getNoteNumber());
Console.print(copy.getNoteNumber());

// Context: When processing MIDI event lists (e.g., remapping note numbers
// or adjusting velocities), dump() provides a quick way to inspect each
// event's state before and after modification.

const var mp = Synth.getMidiPlayer("Player1");
var eventList = mp.getEventList();

for (e in eventList)
{
    if (e.isNoteOn())
    {
        Console.print(e.dump());
        // Output: "Type: NoteOn, Channel: 1, Number: 36, Value: 100, EventId: 0, Timestamp: 480, "

        e.setNoteNumber(60);
        e.setVelocity(80);

        Console.print(e.dump());
        // Output: "Type: NoteOn, Channel: 1, Number: 60, Value: 80, EventId: 0, Timestamp: 480, "
    }
}

// Context: A release trigger script stores NoteOn events and records when
// each key was pressed. On NoteOff, it reads the stored event's note number
// to look up the press time and calculate hold duration.

const var holder = Engine.createMessageHolder();
const var uptimes = [];
uptimes.reserve(128);

for (i = 0; i < 128; i++)
    uptimes[i] = 0.0;

inline function handleNoteOn()
{
    Message.store(holder);
    // Use getNoteNumber() on the stored event to index into per-key arrays
    uptimes[holder.getNoteNumber()] = Engine.getUptime();
}

inline function handleNoteOff()
{
    Message.store(holder);

    // Calculate how long this specific note was held
    local duration = Engine.getUptime() - uptimes[holder.getNoteNumber()];

    if (duration < 0.8)
        Console.print("Short press: " + holder.getNoteNumber());
    else
        Console.print("Long press: " + holder.getNoteNumber());
}

// Context: A sampler that intercepts NoteOn events, stores them for later,
// and re-injects modified copies when the key is released. The hold duration
// determines which sample group to trigger.

const var holder = Engine.createMessageHolder();
const var uptimes = [];
uptimes.reserve(128);

for (i = 0; i < 128; i++)
    uptimes[i] = 0.0;

// Called from onNoteOn callback
inline function handleNoteOn()
{
    Message.store(holder);
    uptimes[Message.getNoteNumber()] = Engine.getUptime();

    // Suppress the original NoteOn - we'll trigger our own later
    Message.ignoreEvent(true);
}

// Called from onNoteOff callback
inline function handleNoteOff()
{
    // Store the NoteOff into the same holder (captures note number for matching)
    Message.store(holder);

    local duration = Engine.getUptime() - uptimes[holder.getNoteNumber()];
    local useShortRelease = duration < 0.8;

    // Select sample group based on how long the note was held
    Sampler.setActiveGroup(useShortRelease ? 1 : 2);
    holder.setGain(-6);

    Synth.addMessageFromHolder(holder);
}

// Context: When processing a MIDI sequence from MidiPlayer.getEventList(),
// use isNoteOn() to filter the array before modifying note properties.

const var mp = Synth.getMidiPlayer("Player1");
mp.setUseTimestampInTicks(true);

var eventList = mp.getEventList();

// Filter to only NoteOn events for analysis or modification
var noteOnEvents = eventList.filter(function(e)
{
    return e.isNoteOn();
});

// Remap note numbers using a conversion table
const var NOTE_MAP = {36: 60, 37: 62, 38: 64, 39: 65};

for (e in eventList)
{
    local nn = e.getNoteNumber();

    if (isDefined(NOTE_MAP[nn]))
    {
        if (e.isNoteOn() || e.isNoteOff())
            e.setNoteNumber(NOTE_MAP[nn]);
    }
}

mp.flushMessageList(eventList);

// Context: A sequencer stores both note and controller data. CC events
// and pitch bend events are both created through the controller API,
// using virtual CC number 128 for pitch bend type coercion.

const var PITCH_BEND_CC = 128;

inline function addControllerEvent(eventList, ccNumber, value, startTick)
{
    local cc = Engine.createMessageHolder();

    // Virtual CC 128 sets type to PitchBend automatically
    if (ccNumber == PITCH_BEND_CC)
        cc.setType(cc.PitchBend);
    else
        cc.setType(cc.Controller);

    cc.setChannel(1);
    cc.setControllerNumber(ccNumber);

    local intValue = Math.range(Math.floor(value * 128.0), 0, 127);
    cc.setControllerValue(intValue);
    cc.setTimestamp(Math.max(0, startTick));

    eventList.push(cc);
}

// Usage: add a mod wheel CC and a pitch bend to a sequence
var events = [];
addControllerEvent(events, 1, 0.5, 0);      // CC#1 (mod wheel) = 64
addControllerEvent(events, PITCH_BEND_CC, 0.5, 240);  // Pitch bend = 64

Console.print(events[0].dump());
Console.print(events[1].dump());

// Context: When re-injecting stored events (e.g., release samples triggered
// on NoteOff), setGain() attenuates the event independently of the original
// velocity. This separates volume control from velocity-based sample selection.

const var holder = Engine.createMessageHolder();

inline function handleNoteOff()
{
    Message.store(holder);

    // Reduce the release sample volume by 6 dB relative to the original
    holder.setGain(-6);

    Synth.addMessageFromHolder(holder);
}

// Context: When exporting a multi-channel sequence to a single MIDI file,
// each track's events need their timestamps offset to account for tempo
// scaling and sequential stem placement.

const var mp = Synth.getMidiPlayer("Player1");
mp.setUseTimestampInTicks(true);

var events = [];
var trackList = mp.getEventList();
var stemOffset = 0;
var ticksPerQuarter = mp.getTicksPerQuarter();

// Remap timestamps relative to a stem offset position
for (event in trackList)
{
    local originalTick = event.getTimestamp();
    event.setTimestamp(stemOffset + originalTick);
    events.push(event);
}

// Next stem starts after this track's content
stemOffset += ticksPerQuarter * 8;

// Context: A step sequencer reads velocity values from a slider pack and
// constructs a complete MIDI sequence as NoteOn/NoteOff pairs, then flushes
// the list to a MidiPlayer for playback.

const var mp = Synth.getMidiPlayer("Player1");
const var sliderPack = Content.getComponent("StepSliderPack");

mp.setUseTimestampInTicks(true);

const var SIXTEENTH_TICKS = 120; // Ticks per sixteenth note (at 480 PPQN)

inline function rebuildSequence()
{
    local list = [];
    list.reserve(sliderPack.getNumSliders() * 2);

    for (i = 0; i < sliderPack.getNumSliders(); i++)
    {
        local vel = sliderPack.getSliderValueAt(i);

        if (vel > 0.0)
        {
            local on = Engine.createMessageHolder();
            local off = Engine.createMessageHolder();

            on.setType(on.NoteOn);
            off.setType(on.NoteOff);

            on.setChannel(1);
            off.setChannel(1);

            on.setNoteNumber(64);
            off.setNoteNumber(64);

            on.setVelocity(parseInt(vel * 127));

            on.setTimestamp(i * SIXTEENTH_TICKS);
            off.setTimestamp(i * SIXTEENTH_TICKS + parseInt(0.99 * SIXTEENTH_TICKS));

            list.push(on);
            list.push(off);
        }
    }

    mp.flushMessageList(list);
}

