// Context: Load a MIDI file, process the events (remap notes, adjust
// velocities), then save back to a new location

const var mp = Synth.getMidiPlayer("MidiPlayer1");

inline function processAndSave(inputFile, outputFile, trackIndex)
{
    mp.setFile(inputFile, true, true);
    mp.setTrack(trackIndex);

    local events = mp.getEventList();

    // Remap note numbers using a conversion table
    for (e in events)
    {
        local nn = e.getNoteNumber();

        if (e.isNoteOn())
            e.setVelocity(Math.min(127, parseInt(e.getVelocity() * 1.1)));

        e.setNoteNumber(nn + 12);
    }

    mp.flushMessageList(events);
    mp.saveAsMidiFile(outputFile, trackIndex - 1); // track index is zero-based here
}

// Context: When a MIDI sequence contains embedded CC messages (e.g. for
// filter cutoff, send levels, pitch), enable this so the automation
// handler routes them to the mapped parameters during playback.

const var mp = Synth.getMidiPlayer("MidiPlayer1");

// Enable CC routing to the global automation handler
mp.setAutomationHandlerConsumesControllerEvents(true);

// Now CC messages in the MIDI sequence will be sent to the
// MidiAutomationHandler, which routes them to mapped parameters.
// The CC events are consumed (not passed through the signal chain).

