examples.code:
// Context: When you obtain a generic MidiProcessor handle (e.g. from a loop
// over all MIDI processors), cast it to MidiPlayer to access playback methods.
// The reverse cast (MidiPlayer.asMidiProcessor()) is used for state serialization.

const var mp = Synth.getMidiProcessor("MIDIPlayer1");

// Cast to MidiPlayer -- throws if the module is not a MidiPlayer
const var player = mp.asMidiPlayer();

// Now you can use MidiPlayer-specific methods
player.setPlaybackPosition(0.0);
player.play(0);

// The reverse: cast MidiPlayer back to MidiProcessor for exportState()
const var player2 = Synth.getMidiPlayer("MIDIPlayer2");
const var mp2 = player2.asMidiProcessor();
var savedState = mp2.exportState();

// Context: A custom preset system saves the UI control values of each script
// processor separately from modulators and effects. exportScriptControls()
// captures only knob/slider/button values without the script code itself,
// and restoreScriptControls() restores them without triggering recompilation.

const var midiProcessorIds = Synth.getIdList("MidiProcessor");
const var presetData = {"midiProcessors": {}};

inline function savePresetData()
{
    for (id in midiProcessorIds)
    {
        local mp = Synth.getMidiProcessor(id);

        // exportScriptControls only works on script processors --
        // built-in modules like Transposer or Arpeggiator will throw an error.
        // Use exportState() for those instead.
        presetData.midiProcessors[id] = mp.exportScriptControls();
    }
}

inline function loadPresetData()
{
    for (id in midiProcessorIds)
    {
        local mp = Synth.getMidiProcessor(id);

        if (typeof presetData.midiProcessors[id] == void)
            continue;

        // Restores UI control values without recompiling the script
        mp.restoreScriptControls(presetData.midiProcessors[id]);
    }
}

// Context: A preset system that allows users to "lock" certain effects so
// they persist when loading a new preset. The state is captured as base64
// before the preset loads and restored after.

const var NUM_FX_SLOTS = 3;
const var fxModules = [];
const var fxLockStates = [];
const var fxSavedStates = [];

for (i = 0; i < NUM_FX_SLOTS; i++)
{
    fxModules.push(Synth.getEffect("FX" + (i + 1)));
    fxLockStates.push(false);
    fxSavedStates.push("");
}

// Call before loading a new preset
inline function captureLockedStates()
{
    for (i = 0; i < NUM_FX_SLOTS; i++)
    {
        // Only capture state for locked slots
        fxSavedStates[i] = fxLockStates[i] ? fxModules[i].exportState() : "";
    }
}

// Call after loading a new preset
inline function restoreLockedStates()
{
    for (i = 0; i < NUM_FX_SLOTS; i++)
    {
        if (fxSavedStates[i].length > 0)
        {
            Console.print("Restoring locked state for " + fxModules[i].getId());
            fxModules[i].restoreState(fxSavedStates[i]);
        }
    }
}

// Context: Export the state of multiple processors for import/export
// functionality outside the standard preset system.

const var fxChain = [Synth.getEffect("EQ1"),
                     Synth.getEffect("Compressor1"),
                     Synth.getEffect("Delay1")];

inline function saveChainToFile(file)
{
    local content = {};

    for (fx in fxChain)
        content[fx.getId()] = fx.exportState();

    file.writeObject(content);
}

// Context: When loading a factory preset stored as a JSON object, restore
// each script processor's UI controls from the saved base64 strings.
// This avoids recompilation -- only knob/slider/button values change.

const var presetStoragePanel = Content.getComponent("PresetStorage");

inline function onPresetLoad(component, value)
{
    if (typeof value != "object")
        return;

    local midiIds = Synth.getIdList("MidiProcessor");

    for (id in midiIds)
    {
        // Skip if this processor wasn't in the saved preset
        if (typeof value.midiProcessors[id] == void)
            continue;

        local mp = Synth.getMidiProcessor(id);
        mp.restoreScriptControls(value.midiProcessors[id]);
    }
}

presetStoragePanel.setControlCallback(onPresetLoad);

// Context: MidiPlayer modules need generic state serialization for custom
// preset loading. Cast to MidiProcessor to access exportState/restoreState,
// then continue using the MidiPlayer handle for playback control.

const var NUM_PLAYERS = 4;
const var players = [];

for (i = 0; i < NUM_PLAYERS; i++)
    players.push(Synth.getMidiPlayer("MIDIPlayer" + (i + 1)));

inline function loadPatternData(patternObject)
{
    if (!isDefined(patternObject.MidiData))
        return;

    for (i = 0; i < NUM_PLAYERS; i++)
    {
        // Cast MidiPlayer to MidiProcessor for state restore
        local mp = players[i].asMidiProcessor();

        mp.restoreState(patternObject.MidiData[i]);
        mp.setAttribute(mp.PlaybackSpeed, patternObject.Rate[i]);

        // Back to MidiPlayer handle for playback operations
        players[i].setPlaybackPosition(0.0);
    }
}

// Context: When loading an effect into a dynamic slot, restore its default
// state from a pre-captured base64 string. This ensures predictable initial
// parameter values regardless of previous slot contents.

const var slot = Synth.getSlotFX("FXSlot1");

// Pre-captured default states for each effect type
const var defaultStates = {
    "Delay": "base64-encoded-default-state...",
    "Reverb": "base64-encoded-default-state...",
    "Filter": "base64-encoded-default-state..."
};

inline function loadEffect(effectName)
{
    slot.setEffect(effectName);

    local fx = slot.getCurrentEffect();

    if (isDefined(defaultStates[effectName]))
        fx.restoreState(defaultStates[effectName]);
}

// Context: MidiProcessor handles to built-in modules expose dynamic constants
// for each parameter. Use these instead of raw indices.

const var arp = Synth.getMidiProcessor("Arpeggiator1");

// Dynamic constants like NumStepSlider and SequenceComboBox are
// registered at construction time from the module's parameter list
inline function onStepCountChanged(component, value)
{
    arp.setAttribute(arp.NumStepSlider, value);
}

inline function onDirectionChanged(component, value)
{
    // 1 = Up, 2 = Down, 3 = Up+Down, 5 = Random
    arp.setAttribute(arp.SequenceComboBox, parseInt(value));
}

Content.getComponent("StepCount").setControlCallback(onStepCountChanged);
Content.getComponent("Direction").setControlCallback(onDirectionChanged);

// Context: When one script processor controls another, use dynamic constants
// from the target module. For articulation switching, muters use an
// ignoreButton parameter to gate MIDI to specific sample groups.

const var sustainMuter = Synth.getMidiProcessor("SustainMuter");
const var staccatoMuter = Synth.getMidiProcessor("StaccatoMuter");
const var legatoScript = Synth.getMidiProcessor("LegatoHandler");

inline function setArticulation(index)
{
    // Each muter's ignoreButton constant maps to its mute toggle parameter
    sustainMuter.setAttribute(sustainMuter.ignoreButton, index != 0);
    staccatoMuter.setAttribute(staccatoMuter.ignoreButton, index != 1);

    // Script processors also expose their parameters as dynamic constants
    legatoScript.setAttribute(legatoScript.btnMute, index != 2);
}

// Context: The AssignableObject interface allows mp["ParamName"] = value
// as shorthand for setAttribute. Writing works; reading does not.

const var transposer = Synth.getMidiProcessor("Transposer1");

// Bracket write delegates to setAttribute -- this works
transposer["SemiTones"] = 12;

// Equivalent explicit call
transposer.setAttribute(transposer.SemiTones, 12);

// WARNING: bracket read always returns 1.0 -- use getAttribute instead
var v = transposer.getAttribute(transposer.SemiTones); // correct
// var v = transposer["SemiTones"]; // always returns 1.0!

