// Context: A modulation matrix allows users to route global sources to targets
// at runtime. This creates a time-variant receiver that continuously tracks
// the source modulator's output.

const var globalLFO = Synth.getModulator("GlobalLFO1");
const var filter = Synth.getEffect("PolyFilter1");
const var GAIN_CHAIN = 0;

// Validate the target before creating the connection
if (filter.getId() != "")
{
    // Create a receiver that continuously tracks the LFO output
    const var receiver = filter.addGlobalModulator(GAIN_CHAIN, globalLFO, "LFO_to_Filter");
    receiver.setIntensity(0.5);
}

// Context: LFOs and envelopes need continuous tracking (addGlobalModulator),
// while velocity and random sources only produce a value at voice start
// (addStaticGlobalModulator). Some targets may also force static routing.

const var sourceMod = Synth.getModulator("GlobalLFO1");
const var target = Synth.getEffect("PolyFilter1");
const var GAIN_CHAIN = 0;

// Use static routing for voice-start sources or targets that don't
// support continuous modulation; dynamic routing otherwise
const var useStatic = false;
var newMod;

if (useStatic)
    newMod = target.addStaticGlobalModulator(GAIN_CHAIN, sourceMod, "Mod_Connection");
else
    newMod = target.addGlobalModulator(GAIN_CHAIN, sourceMod, "Mod_Connection");

newMod.setIntensity(1.0);

// To remove the connection later:
// Synth.removeModulator(newMod);

// Context: When building a modulation matrix, envelope sources need per-voice
// modulators created at the target. This creates an AHDSR in the target's
// gain chain and initializes its parameters from the current UI state.

const var filterEffect = Synth.getEffect("PolyFilter1");
const var GAIN_CHAIN = 0;

// Create an AHDSR modulator in the filter's gain chain
const var envMod = filterEffect.addModulator(GAIN_CHAIN, "AHDSR", "FilterEnvMod");

// Initialize envelope parameters from UI knob values
envMod.setAttribute(envMod.Attack, attackKnob.getValue());
envMod.setAttribute(envMod.Decay, decayKnob.getValue());
envMod.setAttribute(envMod.Sustain, sustainKnob.getValue());
envMod.setAttribute(envMod.Release, releaseKnob.getValue());

// Reduce CPU overhead for modulators that don't need sample-accurate updates
envMod.setAttribute(envMod.EcoMode, 32);

envMod.setIntensity(1.0);

// Context: Voice-start sources (velocity, key number, random) produce a single
// value at note-on that does not change during the note. Using the static
// variant avoids the CPU cost of per-block polling for a value that is constant.

const var globalVelocity = Synth.getModulator("GlobalVelocity1");
const var filter = Synth.getEffect("PolyFilter1");
const var GAIN_CHAIN = 0;

// Static receiver: samples the source value once at voice start
const var velMod = filter.addStaticGlobalModulator(
    GAIN_CHAIN, globalVelocity, "Velocity_to_Filter"
);

velMod.setIntensity(0.7);

// To remove the connection later:
// Synth.removeModulator(velMod);

const var mod = Synth.getModulator("TableEnvelope1");
const var tp = mod.asTableProcessor();

if (isDefined(tp))
{
    tp.addTablePoint(0, 0.5, 0.8);
    tp.reset(0);
}

// Context: An "FX Lock" feature lets users freeze their effect chain so it
// survives preset switches. Before a preset loads, each effect's state is
// captured as base64. After the preset loads, locked effects are restored.

const var eq = Synth.getEffect("ParametricEQ1");
const var comp = Synth.getEffect("Compressor1");
const var limiter = Synth.getEffect("Limiter1");

const var fxModules = [eq, comp, limiter];

// Capture state before preset change
var savedStates = {};

for (fx in fxModules)
    savedStates[fx.getId()] = fx.exportState();

// ... preset loads here ...

// Restore locked effects after preset change
for (fx in fxModules)
{
    local state = savedStates[fx.getId()];

    if (state.length > 0)
        fx.restoreState(state);
}

// Context: Users can export their effect settings to a file and reload them
// in another session or preset. exportState produces a base64 string that
// can be stored as a JSON property.

const var eq = Synth.getEffect("ParametricEQ1");
const var comp = Synth.getEffect("Compressor1");

inline function saveFXToFile(file)
{
    local content = {};
    content[eq.getId()] = eq.exportState();
    content[comp.getId()] = comp.exportState();
    file.writeObject(content);
}

inline function loadFXFromFile(file)
{
    local content = file.loadAsObject();

    if (isDefined(content))
    {
        if (isDefined(content[eq.getId()]))
            eq.restoreState(content[eq.getId()]);

        if (isDefined(content[comp.getId()]))
            comp.restoreState(content[comp.getId()]);
    }
}

// Context: A small panel next to each modulator source shows its current
// output level as a colour blend from idle (dark) to active (bright).

const var lfo = Synth.getModulator("LFO1");

const var ledPanel = Content.addPanel("LFOLed", 0, 0);
ledPanel.set("width", 12);
ledPanel.set("height", 12);

ledPanel.data.mod = lfo;
ledPanel.data.value = 0.0;

ledPanel.setPaintRoutine(function(g)
{
    g.setColour(Colours.mix(0xFF404040, 0xFFFFF600, this.data.value));
    g.fillEllipse(this.getLocalBounds(2));
});

ledPanel.setTimerCallback(function()
{
    this.data.value = this.data.mod.getCurrentLevel();
    this.repaint();
});

ledPanel.startTimer(30);

// Context: Shows the combined effect of a modulator on a knob's value by
// polling the modulation chain's output level and drawing an arc.

const var filter = Synth.getEffect("PolyFilter1");

// Access the gain modulation chain (chain index 0) of the filter
const var modChain = filter.getModulatorChain(0);

const var overlayPanel = Content.addPanel("ModOverlay", 0, 0);
overlayPanel.data.modChain = modChain;
overlayPanel.data.lastModValue = 0.0;

overlayPanel.setTimerCallback(function()
{
    local modValue = this.data.modChain.getCurrentLevel();

    // Smooth the display value to avoid jitter
    local delta = Math.abs(modValue - this.data.lastModValue);

    if (delta > 0.005)
    {
        this.data.lastModValue = this.data.lastModValue * 0.85 + 0.15 * modValue;
        this.repaintImmediately();
    }
});

overlayPanel.startTimer(30);

// Context: To show how much modulation is being applied to a parameter,
// access the target's modulation chain and poll getCurrentLevel in a timer.

const var synth = Synth.getChildSynth("Oscillator1");

// Chain index 0 = gain modulation, 1 = pitch modulation (typical layout)
const var gainChain = synth.getModulatorChain(0);
const var pitchChain = synth.getModulatorChain(1);

const var gainDisplay = Content.addPanel("GainModDisplay", 0, 0);
gainDisplay.data.modChain = gainChain;

gainDisplay.setTimerCallback(function()
{
    // getCurrentLevel returns the combined output of all modulators in the chain
    local level = this.data.modChain.getCurrentLevel();
    // Use level for visualization (0.0 to 1.0 for gain chains)
    this.repaint();
});

gainDisplay.startTimer(30);

// Context: When using the Builder API to create modules, restoreState can
// apply a pre-configured state captured from the HISE IDE. This avoids
// setting dozens of individual attributes manually.

const var builder = Synth.createBuilder();

// Create an EQ module via the Builder
const var eqModule = builder.create("ParametricEQ", "ChannelEQ", parentChain, -1);
const var eq = builder.get(eqModule, builder.InterfaceTypes.Effect);

// Apply a pre-captured base64 state (exported from HISE IDE)
const var EQ_DEFAULT_STATE = "782.3oc0V0saaCDE..."; // truncated for brevity
eq.restoreState(EQ_DEFAULT_STATE);

// The EQ now has all bands, frequencies, and gains pre-configured
eq.setBypassed(true); // start bypassed until the user enables it

// Context: When creating modulators at runtime (e.g., for a modulation matrix),
// their parameters need to be initialized from the current UI state.

const var envelope = Synth.getModulator("GainEnvelope1");

// Use the dynamic parameter constants -- names depend on modulator type
envelope.setAttribute(envelope.Attack, 20.0);
envelope.setAttribute(envelope.Hold, 0.0);
envelope.setAttribute(envelope.Decay, 500.0);
envelope.setAttribute(envelope.Sustain, 0.7);
envelope.setAttribute(envelope.Release, 200.0);

// EcoMode reduces CPU for modulators that don't need sample-accurate updates
envelope.setAttribute(envelope.EcoMode, 32);

// Context: The bracket operator provides a concise alternative for setting
// attributes by name. Useful when the parameter name is in a variable.

const var lfo = Synth.getModulator("LFO1");

// These two lines are equivalent:
lfo.setAttribute(lfo.Frequency, 4.0);
lfo["Frequency"] = 4.0;

// Useful when iterating parameter names from a different modulator
const var envelope = Synth.getModulator("GainEnvelope1");
const var params = ["Attack", "Decay", "Sustain", "Release"];
const var values = [10.0, 300.0, 0.8, 150.0];

for (i = 0; i < params.length; i++)
    envelope[params[i]] = values[i];

// Context: A common pattern is using bypass to enable/disable optional modulators
// based on UI toggle buttons. The negation (!value) maps button on -> unbypassed.

const var filterKeyMod = Synth.getModulator("FilterKeyFollow1");

inline function onKeyFollowToggle(component, value)
{
    filterKeyMod.setBypassed(!value);
}

keyFollowButton.setControlCallback(onKeyFollowToggle);

// Context: Mode switching often requires bypassing one set of modules while
// activating another. This pattern uses a single index to toggle between
// two processing paths.

const var msEncoder = Synth.getEffect("MSEncoder1");
const var msDecoder = Synth.getEffect("MSDecoder1");
const var stereoEQ = Synth.getEffect("StereoEQ");
const var midEQ = Synth.getEffect("MidEQ");
const var sideEQ = Synth.getEffect("SideEQ");

inline function onEqModeControl(component, value)
{
    local isMidSide = parseInt(value) == 1;

    msEncoder.setBypassed(!isMidSide);
    msDecoder.setBypassed(!isMidSide);
    stereoEQ.setBypassed(isMidSide);
    midEQ.setBypassed(!isMidSide);
    sideEQ.setBypassed(!isMidSide);
}

eqModeSelector.setControlCallback(onEqModeControl);

// Context: Pitch-mode modulators use semitones (-12 to 12) for intensity.
// A common pattern is letting users configure pitch wheel range.

const var pitchMod1 = Synth.getModulator("PitchWheel1");
const var pitchMod2 = Synth.getModulator("PitchWheel2");

inline function onPitchRangeControl(component, value)
{
    // value is in semitones (e.g., 2.0 for whole-tone bend range)
    pitchMod1.setIntensity(value);
    pitchMod2.setIntensity(value);
}

pitchRangeKnob.setControlCallback(onPitchRangeControl);

// Context: The intensity range depends on the parent chain's modulation mode.
// GainMode uses 0.0-1.0, PitchMode uses -12.0 to 12.0 (semitones).

const var gainMod = Synth.getModulator("VelocityMod1");
const var pitchMod = Synth.getModulator("PitchEnvelope1");

// GainMode: 1.0 = full modulation depth
gainMod.setIntensity(1.0);

// PitchMode: 12.0 = full octave range, 1.0 = only 1 semitone
pitchMod.setIntensity(12.0);

// Context: When creating MatrixModulators for a modulation matrix via the
// Builder API, pitch targets need specific bipolar and intensity settings.
// Disabling bipolar ensures the modulation range starts from zero.

const var builder = Synth.createBuilder();

// Create a MatrixModulator in the pitch chain of an oscillator group
const var matrixModule = builder.create(
    builder.Modulators.MatrixModulator, "PitchMod", oscGroup, pitchChainIndex
);

const var mod = builder.get(matrixModule, builder.InterfaceTypes.Modulator);

// For pitch targets: disable bipolar so range is 0..intensity (not -intensity..+intensity)
mod.setIsBipolar(false);

// Set pitch range in semitones
mod.setIntensity(12.0);

mod.setMatrixProperties({
	InputRange: // defines the range of the UI knob
	{
		min: 0.0,
		max: 1.0,
		middlePosition: 0.5,
		mode: "NormalizedPercentage",
		stepSize: 0.0,
	},
	OutputRange: // defines the range of the scaled modulation output signal
	{
		min: 0.0,
		max: 1.0,
		middlePosition: 0.5,
		stepSize: 0.0,
		UseMidPositionAsZero: false
	}
});

