// Context: Route a stereo source to a user-selected DAW output pair,
// falling back to stereo if the host doesn't support the channel count.

const var rm = Synth.getRoutingMatrix("MySynth");

inline function onOutputSelectorControl(component, value)
{
    local outputPair = parseInt(value) - 1;
    local destL = outputPair * 2;
    local destR = outputPair * 2 + 1;

    // addConnection returns false if the destination channel is unavailable
    rm.addConnection(0, destL);
    local ok = rm.addConnection(1, destR);

    if (!ok)
    {
        // Host doesn't support this channel count -- fall back to stereo
        rm.addConnection(0, 0);
        rm.addConnection(1, 1);
    }
}

const var outputSelector = Content.getComponent("OutputSelector");
outputSelector.setControlCallback(onOutputSelectorControl);

// Context: Each channel strip routes its stereo output to a selectable
// DAW output pair. A master matrix passes all channels through when
// multi-output is enabled, or folds everything to stereo when disabled.

const var NUM_CHANNELS = 4;
const var masterMatrix = Synth.getRoutingMatrix("MasterSynth");
const var channelMatrices = [];

for (i = 0; i < NUM_CHANNELS; i++)
    channelMatrices.push(Synth.getRoutingMatrix("Channel " + (i + 1)));

// Expand master matrix for multi-output
masterMatrix.setNumChannels(16);

inline function enableMultiOutput(enable)
{
    masterMatrix.clear();

    if (enable)
    {
        // Pass all channel pairs through to separate DAW outputs
        for (i = 0; i < 16; i++)
        {
            masterMatrix.addConnection(i * 2, i * 2);
            masterMatrix.addConnection(i * 2 + 1, i * 2 + 1);
        }
    }
    else
    {
        // Fold everything to stereo
        masterMatrix.addConnection(0, 0);
        masterMatrix.addConnection(1, 1);
    }
}

inline function setChannelOutput(channelIndex, outputPair)
{
    local matrix = channelMatrices[channelIndex];
    matrix.addConnection(0, outputPair * 2);
    matrix.addConnection(1, outputPair * 2 + 1);
}

// Context: When constructing a multichannel module tree with the Builder API,
// each effect is isolated to process only its designated stereo pair within
// a 6-channel internal bus.

const var b = Synth.createBuilder();

// Create a synth with 6 internal channels (3 stereo layers)
local synth = b.create(b.SoundGenerators.SilentSynth, "MySynth", 0, b.ChainIndexes.Direct);
local synthMatrix = b.get(synth, b.InterfaceTypes.RoutingMatrix);
synthMatrix.setNumChannels(6);

// Mix channels 2-5 down to the main stereo pair
synthMatrix.addConnection(2, 0);
synthMatrix.addConnection(3, 1);
synthMatrix.addConnection(4, 0);
synthMatrix.addConnection(5, 1);

// Create effects that each process only one stereo pair
local labels = ["A", "B", "C"];

for (i = 0; i < 3; i++)
{
    local fx = b.create(b.Effects.HardcodedPolyphonicFX, "FX_" + labels[i], synth, b.ChainIndexes.FX);
    local fxMatrix = b.get(fx, b.InterfaceTypes.RoutingMatrix);

    // Isolate this effect to its stereo pair
    fxMatrix.clear();
    fxMatrix.addConnection(i * 2, i * 2);
    fxMatrix.addConnection(i * 2 + 1, i * 2 + 1);
}

b.flush();

// Context: When switching between stereo and multi-output modes, clear
// the matrix first, then rebuild the desired routing from scratch.

const var masterMatrix = Synth.getRoutingMatrix("MasterSynth");
masterMatrix.setNumChannels(16);

inline function onMultiOutToggle(component, value)
{
    masterMatrix.clear();

    if (value)
    {
        // Multi-out: pass all stereo pairs through
        for (i = 0; i < 16; i++)
        {
            masterMatrix.addConnection(i * 2, i * 2);
            masterMatrix.addConnection(i * 2 + 1, i * 2 + 1);
        }
    }
    else
    {
        // Stereo: fold to main output
        masterMatrix.addConnection(0, 0);
        masterMatrix.addConnection(1, 1);
    }
}

const var multiOutButton = Content.getComponent("MultiOutButton");
multiOutButton.setControlCallback(onMultiOutToggle);

// Context: When creating effects in a multichannel signal path,
// clear the default stereo routing first, then connect only the
// target channel pair.

const var b = Synth.createBuilder();

local fx = b.create(b.Effects.HardcodedMasterFX, "ReverbA", parentProc, b.ChainIndexes.FX);
local fxMatrix = b.get(fx, b.InterfaceTypes.RoutingMatrix);

// Remove the default stereo passthrough (0->0, 1->1)
fxMatrix.clear();

// Route only channels 2/3 through this effect
fxMatrix.addConnection(2, 2);
fxMatrix.addConnection(3, 3);

b.flush();

// Context: In a mid/side processing chain, two EQ processors sit between
// LR-to-MS and MS-to-LR converter effects. Each EQ is restricted to one
// channel by removing the other connection from its routing matrix.

const var b = Synth.createBuilder();

// LR-to-MS encoder
local lr2ms = b.create(b.Effects.HardcodedMasterFX, "LR2MS", 0, b.ChainIndexes.FX);

// Mid-only EQ: remove the side channel (channel 1)
local midEq = b.create(b.Effects.CurveEq, "MidEQ", 0, b.ChainIndexes.FX);
b.get(midEq, b.InterfaceTypes.RoutingMatrix).removeConnection(1, 1);

// Side-only EQ: remove the mid channel (channel 0)
local sideEq = b.create(b.Effects.CurveEq, "SideEQ", 0, b.ChainIndexes.FX);
b.get(sideEq, b.InterfaceTypes.RoutingMatrix).removeConnection(0, 0);

// MS-to-LR decoder
local ms2lr = b.create(b.Effects.HardcodedMasterFX, "MS2LR", 0, b.ChainIndexes.FX);

b.flush();

// Context: Before configuring multichannel routing, expand the matrix
// to accommodate all needed output pairs. This also relaxes the stereo
// constraint that would otherwise auto-correct connections.

const var masterMatrix = Synth.getRoutingMatrix("MasterSynth");

// Expand to at least 16 channels, or the host's channel count if larger
masterMatrix.setNumChannels(Math.max(16, Engine.getNumPluginChannels()));

// Now multichannel addConnection calls won't be auto-corrected
masterMatrix.addConnection(0, 0);
masterMatrix.addConnection(1, 1);
masterMatrix.addConnection(2, 2);
masterMatrix.addConnection(3, 3);
// ... etc.

// Context: When building a channel strip with the Builder API, expand
// the internal channel count to support multiple stereo layers
// (e.g., 3 layers = 6 channels) routed through dedicated effects.

const var b = Synth.createBuilder();

local synth = b.create(b.SoundGenerators.SilentSynth, "Channel1", 0, b.ChainIndexes.Direct);
local matrix = b.get(synth, b.InterfaceTypes.RoutingMatrix);

// 3 stereo layers = 6 internal channels
matrix.setNumChannels(6);

// Mix layers 2 and 3 down to the main stereo pair
matrix.addConnection(2, 0);
matrix.addConnection(3, 1);
matrix.addConnection(4, 0);
matrix.addConnection(5, 1);

b.flush();

description.details:
### Property Access Patterns

Sample implements AssignableObject, enabling three equivalent access styles:

```javascript
// Integer constant index
var root = sample.get(Sample.Root);
sample.set(Sample.Root, 60);

// Bracket with constant
var root = sample[Sample.Root];
sample[Sample.Root] = 60;

// Bracket with string identifier
var root = sample["Root"];
sample["Root"] = 60;
```

String identifiers are resolved at parse time via `getCachedIndex()` for runtime performance. The string names match the SampleIds identifiers exactly (e.g., "Root", "HiKey", "LoVel").

### Return Type Behavior

See `get()` for details. All non-FileName properties return integers, including Volume (dB) and Pan.

### Value Clipping and Dynamic Ranges

Values are automatically clipped to valid ranges on `set()`. Ranges are interdependent -- see `getRange()` for querying current valid bounds. Setting certain properties triggers cascading adjustments to dependent properties (e.g., SampleStart changes may adjust LoopXFade, LoopStart, SampleStartMod). See `set()` for the full list.

### Custom Properties

See `getCustomProperties()`. This data is transient and NOT persisted in the sample map.

### Multi-Mic Audio Loading

See `loadIntoBufferArray()`. Returns a flat array of channel buffers across all mic positions.

