// Context: In a sample curation tool, remove an unwanted sample from
// the map and reassign another sample to fill its key position.

const var sampler = Synth.getSampler("Sampler1");

// Get the sample to delete (e.g., from GUI selection)
const var toDelete = Sampler.createListFromGUISelection()[0];

if (isDefined(toDelete))
{
    // Remember the key position before deletion
    local noteNumber = toDelete.get(Sample.Root);

    // Find a replacement sample (e.g., the last sample in the map)
    const var allSamples = sampler.createSelection(".*");
    var replacement = -1;

    for (s in allSamples)
    {
        // Skip the sample we're about to delete
        if (s.refersToSameSample(toDelete))
            continue;

        replacement = s;
    }

    // Delete the unwanted sample
    toDelete.deleteSample();
    // toDelete is now invalid - do not use it again

    // Remap the replacement to the deleted sample's position
    if (replacement != -1)
    {
        replacement.set(Sample.Root, noteNumber);
        replacement.set(Sample.LoKey, noteNumber);
        replacement.set(Sample.HiKey, noteNumber);
    }

    Sampler.refreshInterface();
}

// Context: Measure peak loudness of each sample, attach it as custom
// metadata, then sort by peak to assign velocity zones. The metadata
// travels with the Sample object through sorting.

const var sampler = Synth.getSampler("Sampler1");
const var selection = sampler.createSelection(".*");

// Phase 1: Analyze peaks and attach to each sample
var minDb = 0.0;
var maxDb = -100.0;

for (s in selection)
{
    local buf = s.loadIntoBufferArray()[0];
    local peak = Engine.getDecibelsForGainFactor(buf.getMagnitude());

    // Attach peak as transient metadata - not saved to sample map
    s.getCustomProperties().Peak = peak;
    minDb = Math.min(minDb, peak);
    maxDb = Math.max(maxDb, peak);
}

// Store global range on each sample for normalization
for (s in selection)
{
    s.getCustomProperties().MinPeak = minDb;
    s.getCustomProperties().MaxPeak = maxDb;
}

// Phase 2: Sort by peak (custom properties survive the sort)
inline function comparePeaks(s1, s2)
{
    local p1 = s1.getCustomProperties().Peak;
    local p2 = s2.getCustomProperties().Peak;

    if (p1 > p2) return 1;
    if (p2 > p1) return -1;
    return 0;
}

Engine.sortWithFunction(selection, comparePeaks);

// Phase 3: Assign velocity zones based on sorted order
for (i = 0; i < selection.length; i++)
{
    local loVel = parseInt(i * (128 / selection.length));
    local hiVel = parseInt((i + 1) * (128 / selection.length)) - 1;

    selection[i].set(Sample.LoVel, loVel);
    selection[i].set(Sample.HiVel, hiVel);
}

Sampler.refreshInterface();

// Context: Loop property ranges depend on other property values. Query
// getRange() to map a normalized UI slider (0-1) to the valid range.

const var sampler = Synth.getSampler("Sampler1");
const var sound = sampler.createSelection(".*")[0];

// Total sample length for a progress-style display
const var totalSamples = sound.getRange(Sample.SampleEnd)[1];

// Current valid crossfade range depends on LoopStart and SampleStart
local xfadeRange = sound.getRange(Sample.LoopXFade);
Console.print("XFade range: " + xfadeRange[0] + " - " + xfadeRange[1]);

// Map a 0-1 slider value to the valid crossfade range
inline function applyNormalizedXFade(normalizedValue)
{
    local maxXFade = sound.getRange(Sample.LoopXFade)[1];
    // Re-query each time - the range changes when LoopStart moves
    local newValue = parseInt(maxXFade * normalizedValue);
    sound.set(Sample.LoopXFade, newValue);
}

// Context: Load sample audio into a buffer, detect its fundamental
// frequency, and set the root note accordingly. Useful for user-import
// workflows where sample metadata is missing.

const var sampler = Synth.getSampler("Sampler1");
const var sound = sampler.createSelection(".*")[0];

// loadIntoBufferArray returns a flat array: [mic1_L, mic1_R, mic2_L, ...]
// For a mono single-mic sample, index 0 is the only channel.
const var buf = sound.loadIntoBufferArray()[0];

// Detect pitch using the sample's own sample rate
const var freq = buf.detectPitch(sound.getSampleRate());

// Convert frequency to nearest MIDI note
for (i = 0; i < 128; i++)
{
    if (Engine.getFrequencyForMidiNoteNumber(i) > freq)
    {
        local detectedNote = i - 1;
        local currentRoot = sound.get(Sample.Root);

        if (currentRoot != detectedNote)
        {
            Console.print("Pitch: " + Engine.getMidiNoteName(currentRoot)
                + " -> " + Engine.getMidiNoteName(detectedNote));
            sound.set(Sample.Root, detectedNote);
        }
        break;
    }
}

// Context: Analyze peak amplitude of each sample to sort them by
// loudness before assigning velocity layers.

const var sampler = Synth.getSampler("Sampler1");
const var selection = sampler.createSelection(".*");

for (s in selection)
{
    // getMagnitude returns the absolute peak value of the buffer
    local buf = s.loadIntoBufferArray()[0];
    local peakDb = Engine.getDecibelsForGainFactor(buf.getMagnitude());
    Console.print(s.get(Sample.FileName) + ": " + peakDb + " dB");
}

// Context: After sorting samples by peak loudness, assign non-overlapping
