].join("\n"));

// Value 1 = "LowPass" (first selectable item, not the header)
// Value 4 = "Compressor" (headers and separators are skipped)
cb.setValue(1);
Console.print(cb.getItemText()); // "LowPass" -- submenu prefix stripped

// Context: Create and configure combo boxes inside a namespace function that returns
// the configured component. This pattern keeps creation, styling, and callback
// assignment together for reusable selector components.

namespace Selectors
{
    inline function onSelectorChanged(component, value)
    {
        Console.print(component.getId() + ": " + parseInt(value));
    }

    inline function makeSelector(name, items, x, y)
    {
        local cb = Content.addComboBox(name, x, y);
        cb.set("width", 120);
        cb.set("height", 28);
        cb.set("items", items.join("\n"));
        cb.set("text", "Select...");
        cb.set("saveInPreset", false);
        cb.setControlCallback(onSelectorChanged);
        return cb;
    }
}

const var cbWaveform = Selectors.makeSelector("Waveform", ["Sine", "Saw", "Square"], 0, 0);
const var cbFilter = Selectors.makeSelector("FilterType", ["LP", "HP", "BP"], 140, 0);

// Context: A combo box populated from the sample map list drives sample loading.
// The callback uses value-1 to convert from 1-based combo index to 0-based array index.

const var sampleMapList = Sampler.getSampleMapList();

const var cbSampleMap = Content.addComboBox("SampleMapSelector", 0, 0);
cbSampleMap.set("items", sampleMapList.join("\n"));
cbSampleMap.set("saveInPreset", false);

inline function onSampleMapChanged(component, value)
{
    // value arrives as a float (e.g. 1.0), so convert to int for array indexing
    Console.print("Loading map index: " + (parseInt(value) - 1));
}

cbSampleMap.setControlCallback(onSampleMapChanged);

// Context: A single callback handles multiple combo boxes created in a loop.
// The component's ID encodes its role, enabling one function to drive different behaviors.

var dispatchLog = [];

inline function onComboChanged(component, value)
{
    local id = component.getId();
    local idx = parseInt(value) - 1;

    if (id.contains("FilterType"))
        dispatchLog.push("filter:" + idx);
    else if (id.contains("Waveform"))
        dispatchLog.push("waveform:" + idx);
}

// Create combo boxes in a loop, all sharing the same callback
for (i = 1; i <= 2; i++)
{
    local cb = Content.addComboBox("FilterType" + i, (i - 1) * 200, 0);
    cb.set("items", "LP\nHP\nBP");
    cb.set("saveInPreset", false);
    cb.setControlCallback(onComboChanged);
}

// Context: A common pattern for selectors that show only a small dropdown arrow and
// custom-styled popup items. The drawComboBox callback renders just the triangle indicator,
// while separate popup menu functions style the dropdown list.

const var selectorLaf = Content.createLocalLookAndFeel();

selectorLaf.registerFunction("drawComboBox", function(g, obj)
{
    g.setColour(obj.hover ? 0xBBFFFFFF : 0x88FFFFFF);

    // Position the triangle in the right portion of the area
    var triArea = [obj.area[0] + obj.area[2] - obj.area[3],
                   obj.area[1], obj.area[3], obj.area[3]];

    // Shrink and draw a downward-pointing triangle
    triArea = [triArea[0] + 10, triArea[1] + 10,
               triArea[2] - 20, triArea[3] - 20];
    g.fillTriangle(triArea, Math.PI);
});

// Style the popup menu to match
selectorLaf.registerFunction("drawPopupMenuBackground", function(g, obj)
{
    g.fillAll(0xFF222222);
});

selectorLaf.registerFunction("drawPopupMenuItem", function(g, obj)
{
    if (obj.isHighlighted)
    {
        g.setColour(0x22FFFFFF);
        g.fillRect(obj.area);
    }

    g.setColour(obj.isTicked ? Colours.white : 0xAAFFFFFF);
    g.setFont("Default", 13.0);

    var textArea = obj.area.clone();
    textArea[0] += 10;
    g.drawAlignedText(obj.text, textArea, "left");
});

const var cbSelector = Content.addComboBox("Selector", 0, 0);
cbSelector.set("items", "Option A\nOption B\nOption C");
cbSelector.setLocalLookAndFeel(selectorLaf);

// Context: A standard-looking combo box LAF that draws a rounded rectangle outline,
// left-aligned text, and a dropdown triangle on the right side.

const var comboLaf = Content.createLocalLookAndFeel();

comboLaf.registerFunction("drawComboBox", function(g, obj)
{
    // Draw outline using the component's itemColour1 property
    g.setColour(obj.itemColour1);
    var r = [obj.area[0] + 2, obj.area[1] + 2,
             obj.area[2] - 4, obj.area[3] - 4];
    g.drawRoundedRectangle(r, r[3] / 2.0, 1.0);

    // Draw the selected item text
    g.setColour(Colours.withMultipliedAlpha(obj.textColour, obj.hover ? 1.0 : 0.8));
    g.setFont("Default", 13.0);
    var textArea = [r[0] + 12, r[1], r[2] - r[3] - 12, r[3]];
    g.drawAlignedText(obj.text, textArea, "left");

    // Draw dropdown triangle on the right
    var triPath = Content.createPath();
    triPath.startNewSubPath(0.0, 0.0);
    triPath.lineTo(1.0, 0.0);
    triPath.lineTo(0.5, 1.0);
    triPath.closeSubPath();

    var triArea = [r[0] + r[2] - r[3], r[1], r[3], r[3]];
    triArea = [triArea[0] + 11, triArea[1] + 11,
               triArea[2] - 22, triArea[3] - 22];
    g.fillPath(triPath, triArea);
});

const var cb = Content.addComboBox("StyledCombo", 0, 0);
cb.set("items", "Sine\nSaw\nSquare\nTriangle");
cb.setLocalLookAndFeel(comboLaf);

// Context: A Broadcaster drives the combo box value from an external source
// (e.g., a zoom level changed elsewhere). The combo box reflects the current
// state without triggering its own callback.

const var ZOOM_LEVELS = [0.75, 1.0, 1.25, 1.5, 2.0];

const var cbZoom = Content.addComboBox("ZoomSelector", 0, 0);
cbZoom.set("items", "75%\n100%\n125%\n150%\n200%");
cbZoom.set("saveInPreset", false);

const var zoomBroadcaster = Engine.createBroadcaster({
    "id": "zoomSync",
    "args": ["value"]
});

// When the broadcaster fires, update the combo box to match
zoomBroadcaster.addListener(cbZoom, "update zoom selector", function(value)
{
    // Find which index matches the zoom value and select it
    local idx = ZOOM_LEVELS.indexOf(value) + 1;
    this.setValue(idx);
});

// Context: When a dependent combo box has its items rebuilt, the previous selection
// index may exceed the new item count. Clamp to the new max before calling changed().

const var cbOption = Content.addComboBox("Option", 0, 0);
cbOption.set("items", "A\nB\nC\nD\nE");
cbOption.set("saveInPreset", false);
cbOption.setValue(4); // Select "D"

// Later, the items are rebuilt with fewer entries
cbOption.set("items", "X\nY\nZ");

// Previous value (4) is now out of range -- clamp to new max (3)
cbOption.setValue(Math.min(parseInt(cbOption.getValue()), cbOption.get("max")));

