// Context: A sequencer stores per-channel step data as Base64 strings
// in a JSON preset. On restore, each channel's data is loaded from
// the string, with "EMPTY" as a sentinel for cleared channels.

const var spd = Engine.createAndRegisterSliderPackData(0);
spd.setNumSliders(8);
spd.setUsePreallocatedLength(8);

// Simulate preset data with Base64-encoded step values
spd.setAllValues(0.0);
spd.setValue(0, 0.9);
spd.setValue(3, 0.5);
var savedState = spd.toBase64();

// Clear and restore
spd.setAllValues(0.0);

inline function restoreChannel(data, b64)
{
    if (b64 == "EMPTY")
        data.setAllValuesWithUndo(0.0);
    else
        data.fromBase64(b64);
}

restoreChannel(spd, savedState);
Console.print(spd.getValue(0)); // 0.9
Console.print(spd.getValue(3)); // 0.5

// Context: A sequencer "rotate" operation shifts all step values by an
// offset amount, wrapping around. Reading via getDataAsBuffer() is
// efficient for copying values, then setValueWithUndo() writes them
// back with undo support.

const var spd = Engine.createAndRegisterSliderPackData(0);
spd.setNumSliders(8);
spd.setAllValues(0.0);
spd.setValue(0, 0.9);
spd.setValue(1, 0.6);
spd.setValue(2, 0.3);

inline function rotateSteps(data, amount, limit)
{
    // Copy current values via buffer reference
    local copy = [];
    copy.reserve(limit);

    for (s in data.getDataAsBuffer())
        copy.push(s);

    // Write rotated values with undo support
    for (i = 0; i < limit; i++)
        data.setValueWithUndo(i, copy[(i + amount) % limit]);
}

rotateSteps(spd, 2, 8);

Console.print(spd.getValue(0)); // 0.3
Console.print(spd.getValue(6)); // 0.9
Console.print(spd.getValue(7)); // 0.6

const var spd1 = Engine.createAndRegisterSliderPackData(0);
const var spd2 = Engine.createAndRegisterSliderPackData(1);

spd1.setNumSliders(4);
spd1.setAllValues(0.5);

// Link spd2 to spd1 -- they now share data
spd2.linkTo(spd1);

// Changes through spd1 are visible through spd2
spd1.setValue(0, 1.0);
Console.print(spd2.getValue(0));

const var spd = Engine.createAndRegisterSliderPackData(0);
