// Context: A step sequencer with multiple channels and parameter modes
// needs many SliderPackData objects that resize without reallocation.

const var NUM_CHANNELS = 4;
const var NUM_MODES = 3;  // e.g., velocity, pitch, probability
const var MAX_STEPS = 32;

const var packs = [];
reg packIndex = 0;

for (i = 0; i < NUM_CHANNELS * NUM_MODES; i++)
{
    packs.push(Engine.createAndRegisterSliderPackData(packIndex));
    packs[packIndex].setNumSliders(MAX_STEPS);
    packs[packIndex].setAllValues(0.0);
    packs[packIndex++].setUsePreallocatedLength(MAX_STEPS);
}

// Later: resize without allocation or value loss
packs[0].setValue(0, 0.8);
packs[0].setNumSliders(16);  // View narrows, value at index 0 preserved
packs[0].setNumSliders(32);  // View widens, all original values still intact

Console.print(packs[0].getValue(0)); // 0.8

// Context: When a note is played during recording, the velocity and
// pitch offset are written to the current step position. Using
// setValueWithUndo() ensures the entire recording can be undone.

const var NUM_MODES = 2;
const var VELOCITY = 0;
const var PITCH = 1;
const var NUM_STEPS = 16;

// Create data packs for velocity and pitch
const var packs = [];
packs.push(Engine.createAndRegisterSliderPackData(0));
packs.push(Engine.createAndRegisterSliderPackData(1));

for (p in packs)
{
    p.setNumSliders(NUM_STEPS);
    p.setAllValues(0.0);
    p.setUsePreallocatedLength(NUM_STEPS);
}

// In onNoteOn: record velocity and pitch at the current step
inline function recordStep(step, velocity, pitchOffset)
{
    packs[VELOCITY].setValueWithUndo(step, velocity / 127.0);
    packs[PITCH].setValueWithUndo(step, pitchOffset);
}

recordStep(0, 100, 0.0);
recordStep(4, 80, 0.2);

