// Context: A synthesizer with a unison/detune feature replaces each incoming note with
// N artificial notes on different MIDI channels. Each channel feeds a different detune
// modulator. The event IDs are tracked per note number for proper cleanup.

// In onInit:
Synth.setShouldKillRetriggeredNote(false);

const var NUM_VOICES = 4;

// Pre-allocate a 2D array: one event ID list per MIDI note
const var eventIds = [];
eventIds.reserve(128);
for(i = 0; i < 128; i++)
{
    eventIds[i] = [];
    eventIds[i].reserve(NUM_VOICES);
}

// In onNoteOn:
inline function onNoteOn()
{
    Message.ignoreEvent(true);

    local noteEventIds = eventIds[Message.getNoteNumber()];
    noteEventIds.clear();

    for(i = 0; i < NUM_VOICES; i++)
    {
        // Each voice uses a different MIDI channel for separate detune routing
        noteEventIds[i] = Synth.addNoteOn(i + 1, Message.getNoteNumber(), Message.getVelocity(), 0);
    }
}

// In onNoteOff:
inline function onNoteOff()
{
    Message.ignoreEvent(true);

    local noteEventIds = eventIds[Message.getNoteNumber()];

    for (id in noteEventIds)
        Synth.noteOffByEventId(id);

    noteEventIds.clear();
}

// Context: A monophonic synth replaces each incoming note with an artificial one.
// When a legato transition occurs, the new note starts with an instant pitch offset
// equal to the interval between old and new notes, then fades to zero over the glide time.

reg lastNote = -1;
reg lastEventId = -1;

const var glideTimeMs = 200;

inline function onNoteOn()
{
    Message.ignoreEvent(true);

    local newId = Synth.addNoteOn(1, Message.getNoteNumber(), Message.getVelocity(), 0);

    if (lastNote != -1)
    {
        Synth.noteOffByEventId(lastEventId);

        // Phase 1: Instantly offset pitch by the interval (in semitones)
        local delta = Message.getNoteNumber() - lastNote;
        Synth.addPitchFade(newId, 0, -delta, 0);

        // Phase 2: Glide from the offset back to the note's natural pitch
        Synth.addPitchFade(newId, glideTimeMs, 0, 0);
    }

    lastEventId = newId;
    lastNote = Message.getNoteNumber();
}

inline function onNoteOff()
{
    if (Message.getNoteNumber() == lastNote)
    {
        Synth.noteOffByEventId(lastEventId);
        lastNote = -1;
    }
}

// Context: For smoother legato transitions, the old note fades out while
// the new note fades in, both with coordinated pitch glides.

reg eventId = -1;
reg lastNote = -1;

const var FADE_TIME = 150;
const var BEND_TIME = 200;

inline function onNoteOn()
{
    Message.ignoreEvent(true);

    if (Synth.isLegatoInterval() && eventId != -1)
    {
        local interval = Message.getNoteNumber() - lastNote;
        local fadeCoarse = -interval;

        // Fade out the old note with pitch bend toward the new pitch
        Synth.addVolumeFade(eventId, FADE_TIME, -100);
        Synth.addPitchFade(eventId, BEND_TIME, interval, 0);

        // Start the new note quietly with pitch offset, then fade in
        eventId = Synth.addNoteOn(1, Message.getNoteNumber(), Message.getVelocity(), 0);
        Synth.addVolumeFade(eventId, 0, -99);
        Synth.addVolumeFade(eventId, FADE_TIME, 0);
        Synth.addPitchFade(eventId, 0, fadeCoarse, 0);
        Synth.addPitchFade(eventId, BEND_TIME, 0, 0);
    }
    else
    {
        eventId = Synth.addNoteOn(1, Message.getNoteNumber(), Message.getVelocity(), 0);
    }

    lastNote = Message.getNoteNumber();
}

// Context: A loop processor stops the previous loop iteration by fading it out
// over 100ms before the next iteration starts. The -100 target volume triggers
// the auto-kill behavior: HISE generates both the volume fade and an automatic
// note-off one sample after the fade completes.

reg lastId = -1;

inline function killLastNote()
{
    if (lastId != -1)
    {
        // -100 = fade to silence AND auto-release the voice
        Synth.addVolumeFade(lastId, 100, -100);
        lastId = -1;
    }
}

// Context: For smooth legato transitions, the old note fades out while the
// new note fades in from silence. Both notes overlap briefly during the crossfade.

reg eventId = -1;

const var CROSSFADE_MS = 150;

inline function onNoteOn()
{
    Message.ignoreEvent(true);

    if (eventId != -1)
    {
        // Fade out old note and auto-kill it
        Synth.addVolumeFade(eventId, CROSSFADE_MS, -100);
    }

    // Start new note at silence, then fade in
    eventId = Synth.addNoteOn(1, Message.getNoteNumber(), Message.getVelocity(), 0);
    Synth.addVolumeFade(eventId, 0, -99);
    Synth.addVolumeFade(eventId, CROSSFADE_MS, 0);
}

// Context: A synth generates an artificial note one octave above each incoming note.
// attachNote links the artificial to the original so that releasing the key
// automatically stops both, eliminating manual note-off tracking in onNoteOff.

// Required: enable the attached note buffer before using attachNote
Synth.setFixNoteOnAfterNoteOff(true);

inline function onNoteOn()
{
    local originalId = Message.getEventId();

    // Generate an artificial note one octave up
    local octaveId = Synth.addNoteOn(1, Message.getNoteNumber() + 12, Message.getVelocity(), 0);

    // Link: when the original note-off arrives, the octave note is auto-killed
    Synth.attachNote(originalId, octaveId);
}

// No onNoteOff handling needed -- the attached note is released automatically

// Context: A multi-channel instrument uses the Builder to create identical
// channel strips with MIDI players, routing matrices, and effect chains.
// The build function is commented out by default and only uncommented when
// the module tree structure needs to change.

// In onInit (commented out after initial build):
// buildModuleTree();

inline function buildModuleTree()
{
    const var b = Synth.createBuilder();
    b.clear();

    const var NUM_CHANNELS = 4;

    for (i = 0; i < NUM_CHANNELS; i++)
    {
        // Create a container synth chain for each channel
        local container = b.create(
            b.SoundGenerators.SynthChain,
            "Channel" + (i + 1), 0,
            b.ChainIndexes.Direct
        );

        // Add a silent synth as the sound generator
        local synth = b.create(
            b.SoundGenerators.SilentSynth,
            "Synth" + (i + 1), container,
            b.ChainIndexes.Direct
        );

        // Configure routing: 6 internal channels mapped to stereo pairs
        local matrix = b.get(synth, b.InterfaceTypes.RoutingMatrix);
        matrix.setNumChannels(6);
        matrix.addConnection(2, 0);
        matrix.addConnection(3, 1);

        // Add effects to the channel strip
        local fx = b.create(
            b.Effects.SimpleGain,
            "Gain" + (i + 1), synth,
            b.ChainIndexes.FX
        );

        b.setAttributes(fx, {"Gain": 0.5});
    }

    b.flush();
}

// Context: A sampler plugin's main interface script handles only UI interactions
// and parameter routing -- it does not modify MIDI events. Deferring callbacks
// moves all MIDI processing to the message thread, allowing safe string
// operations, UI updates, and allocations in callbacks.

// First line of onInit -- before any other code
Synth.deferCallbacks(true);

// With deferred callbacks, you can safely do things like:
const var sampler = Synth.getSampler("MainSampler");
const var filter = Synth.getEffect("Filter");
const var reverb = Synth.getEffect("Reverb");

// Control callbacks can perform UI-safe operations
inline function onFilterControl(component, value)
{
    // String operations are safe in deferred mode
    Console.print("Filter cutoff: " + value);
    filter.setAttribute(filter.Frequency, value);
}

// Context: A legato script or arpeggiator must modify incoming MIDI events
// in real time. The default non-deferred mode runs callbacks on the audio
// thread with sample-accurate timing.

// Explicitly set to false (this is the default, but makes intent clear)
Synth.deferCallbacks(false);

// In non-deferred mode, Message modification works:
inline function onNoteOn()
{
    if (Synth.isLegatoInterval())
        Message.ignoreEvent(true);
}

// Context: A detune/unison script discovers which Script Voice Start Modulators
// exist in the module tree and lets the user assign them to pitch, pan, and gain
// roles via ComboBox dropdowns. This avoids hard-coding processor IDs.

const var pitchSelector = Content.addComboBox("PitchModSelector", 100, 10);
const var gainSelector = Content.addComboBox("GainModSelector", 250, 10);

// getIdList takes a processor TYPE name, not a processor ID
const var voiceStartMods = Synth.getIdList("Script Voice Start Modulator");

pitchSelector.set("items", "None");
gainSelector.set("items", "None");

for (id in voiceStartMods)
{
    pitchSelector.addItem(id);
    gainSelector.addItem(id);
}

reg pitchDetuner;
reg gainDetuner;

inline function onPitchSelectorControl(component, value)
{
    local name = component.getItemText();

    if (name.length > 0)
        pitchDetuner = Synth.getModulator(name);
}

pitchSelector.setControlCallback(onPitchSelectorControl);

// Context: A multi-channel instrument allows each channel to be routed to a
// different stereo output pair. A master routing matrix is resized to accommodate
// all available plugin outputs, and per-channel matrices are reconfigured when
// the user selects a different output bus.

const var NUM_CHANNELS = 4;

// Get routing matrices for the master and each channel container
const var masterMatrix = Synth.getRoutingMatrix("MasterSynth");
const var channelMatrices = [];

for (i = 0; i < NUM_CHANNELS; i++)
    channelMatrices.push(Synth.getRoutingMatrix("Channel" + (i + 1)));

// Resize master to accommodate all plugin output channels
masterMatrix.setNumChannels(Math.max(16, Engine.getNumPluginChannels()));

reg multiOutEnabled = false;

// Toggle between stereo and multi-out mode
inline function onMultiOutToggle(component, value)
{
    multiOutEnabled = value;
    masterMatrix.clear();

    if (value)
    {
        // In multi-out mode, route all stereo pairs 1:1
        for (i = 0; i < 8; i++)
        {
            masterMatrix.addConnection(i * 2, i * 2);
            masterMatrix.addConnection(i * 2 + 1, i * 2 + 1);
        }
    }
    else
    {
        // In stereo mode, everything goes to outputs 1-2
        masterMatrix.addConnection(0, 0);
        masterMatrix.addConnection(1, 1);
    }

    rebuildChannelRouting();
}

// Remap a channel's stereo pair to the selected output bus
inline function rebuildChannelRouting()
{
    for (i = 0; i < NUM_CHANNELS; i++)
    {
        // outputIndex is 0-based: 0 = MASTER (1/2), 1 = 3/4, 2 = 5/6, etc.
        local outputIndex = multiOutEnabled ? (parseInt(selectors[i].getValue()) - 1) : 0;
        local matrix = channelMatrices[i];

        matrix.addConnection(0, outputIndex * 2);
        matrix.addConnection(1, outputIndex * 2 + 1);
    }
}

// Context: A synth with optional portamento uses isLegatoInterval() in the
// onNoteOn callback to detect when a new note arrives while another is held.
// The pitch glide is only applied during legato transitions, not on isolated
// note presses.

reg lastNote = -1;
reg lastEventId = -1;

inline function onNoteOn()
{
    Message.ignoreEvent(true);

    local newId = Synth.addNoteOn(1, Message.getNoteNumber(), Message.getVelocity(), 0);

    if (Synth.isLegatoInterval() && lastNote != -1)
    {
        // Legato transition: kill old note and glide
        Synth.noteOffByEventId(lastEventId);

        local delta = Message.getNoteNumber() - lastNote;
        Synth.addPitchFade(newId, 0, -delta, 0);
        Synth.addPitchFade(newId, 200, 0, 0);
    }

    lastEventId = newId;
    lastNote = Message.getNoteNumber();
}

// Context: A wind instrument sampler applies legato transitions only when
// keys overlap AND the sustain pedal is NOT down. When the pedal is held,
// a different articulation (sustain retrigger) is used instead.

reg articulationType = "";

inline function onNoteOn()
{
    if (Synth.isLegatoInterval() && !Synth.isSustainPedalDown())
    {
        // Legato transition without sustain pedal - apply glide
        articulationType = "legato";
    }
    else
    {
        articulationType = "normal";
    }
}

// Context: A channel selector or preset browser triggers a short audition
// of a sound when the user clicks. The note is scheduled to release after
// a fixed number of samples, so no manual note-off tracking is needed.

inline function previewSound(component, value)
{
    if (value)
    {
        local note = 36 + channelButtons.indexOf(component);
        local id = Synth.playNote(note, 127);

        // Release after ~1 second at 44100 Hz
        Synth.noteOffDelayedByEventId(id, 44100);
    }
}

for (b in channelButtons)
    b.setControlCallback(previewSound);

// Context: A mixer strip or channel selector button triggers a short audition
// of the selected sound. playNote starts the note; noteOffDelayedByEventId
// schedules an automatic note-off after a fixed duration.

inline function previewSound(component, value)
{
    if (value)
    {
        local note = 36 + channelButtons.indexOf(component);
        local id = Synth.playNote(note, 127);

        // Auto-release after ~1 second (at 44100 Hz sample rate)
        Synth.noteOffDelayedByEventId(id, 44100);
    }
}

// Context: A piano plugin keeps a background resonance note playing while any
// keys are held or the sustain pedal is down. A timer provides a delayed release
// so the background note doesn't cut off immediately when the last key is released.

reg id = -1;
reg pedal = false;

inline function handlePedal()
{
    if (Message.getControllerNumber() == 64)
    {
        // Pedal released while no keys held: start delayed release
        if (Message.getControllerValue() < 64 && pedal && Synth.getNumPressedKeys() == 0)
            Synth.startTimer(1.0);

        pedal = Message.getControllerValue() > 64;

        if (pedal)
        {
            Synth.stopTimer();
            if (id == -1)
                id = Synth.playNote(0, 127);
        }
    }
}

inline function handleNoteOn()
{
    if (id == -1)
        id = Synth.playNote(0, 127);

    Synth.stopTimer();
}

inline function handleNoteOff()
{
    if (!pedal && Synth.getNumPressedKeys() == 0)
        Synth.startTimer(1.0);
}

inline function handleTimer()
{
    if (id != -1)
    {
        Synth.noteOffByEventId(id);
        id = -1;
    }
    Synth.stopTimer();
}

// Context: A ScriptPanel handles mouse clicks to simulate a keyboard. playNoteFromUI
// routes notes through the real MIDI input pipeline so isKeyDown() and the on-screen
// keyboard floating tile both reflect the correct state. noteOffFromUI is used for release.

const var keyboard = Content.getComponent("KeyboardPanel");
keyboard.set("allowCallbacks", "Clicks & Hover");

keyboard.data.currentNote = -1;

keyboard.setMouseCallback(function(event)
{
    // Release on mouse leave
    if (!event.hover && this.data.currentNote != -1)
    {
        Synth.noteOffFromUI(1, this.data.currentNote);
        this.data.currentNote = -1;
    }

    // Convert mouse position to note number (simplified)
    local noteNumber = 24 + parseInt(event.x / 15.0);

    if (event.clicked)
    {
        Synth.playNoteFromUI(1, noteNumber, 127);
        this.data.currentNote = noteNumber;
    }

    if (event.mouseUp && this.data.currentNote != -1)
    {
        Synth.noteOffFromUI(1, this.data.currentNote);
        this.data.currentNote = -1;
    }
});

Synth.setModulatorAttribute(1, 0, -12, 0.5);

// Bypass the second pitch modulator
Synth.setModulatorAttribute(2, 1, -13, 1.0);

// Context: A synth with a unison/detune feature generates multiple artificial
// notes per key press, all on the same pitch. Without disabling the retrigger
// kill, each subsequent artificial note would kill the previous one, leaving
// only a single voice instead of the intended unison spread.

// Must be called in onInit before any note generation occurs
Synth.setShouldKillRetriggeredNote(false);

const var NUM_UNISON_VOICES = 4;

inline function onNoteOn()
{
    Message.ignoreEvent(true);

    // Generate N artificial voices on different channels
    for (i = 0; i < NUM_UNISON_VOICES; i++)
    {
        Synth.addNoteOn(i + 1, Message.getNoteNumber(), Message.getVelocity(), 0);
    }
}

// Context: A step sequencer or arpeggiator calculates the timer interval
// from the host tempo and uses startTimer to drive note generation.
// The timer fires on the audio thread for sample-accurate timing.

reg currentStep = 0;
const var NUM_STEPS = 8;

inline function onController()
{
    // Start arpeggiator when a note is held (simplified)
    if (Message.getControllerNumber() == 64 && Message.getControllerValue() > 0)
    {
        // Calculate interval from host BPM for eighth notes
        local bpm = Engine.getHostBpm();
        local eighthNoteSeconds = 30.0 / bpm;
        Synth.startTimer(eighthNoteSeconds);
    }
}

inline function onTimer()
{
    local note = 48 + currentStep;
    local id = Synth.playNote(note, 100);

    // Auto-release after half the step duration
    Synth.noteOffDelayedByEventId(id, parseInt(Engine.getSampleRate() * Synth.getTimerInterval() * 0.5));

    currentStep = (currentStep + 1) % NUM_STEPS;
}

// Context: A piano plugin keeps a background resonance note alive while keys
// are held. When the last key is released, a 1-second timer starts. If no
// new key arrives before the timer fires, the background note is released.
// This prevents abrupt cutoffs during normal playing.

reg backgroundNoteId = -1;

inline function onNoteOff()
{
    if (Synth.getNumPressedKeys() == 0)
        Synth.startTimer(1.0);
}

inline function onNoteOn()
{
    Synth.stopTimer();

    if (backgroundNoteId == -1)
        backgroundNoteId = Synth.playNote(0, 127);
}

inline function onTimer()
{
    if (backgroundNoteId != -1)
    {
        Synth.noteOffByEventId(backgroundNoteId);
        backgroundNoteId = -1;
    }

    Synth.stopTimer();
}

