// Context: OpenGL shaders expect fixed-size arrays. asBuffer(true)
// returns all 128 slots, providing a stable buffer size regardless
// of how many elements are in the stack.

const var keyState = Engine.createUnorderedStack();
const var shader = Content.createShader("keyboard");

// Note events update the stack
inline function handleNote(noteNumber, velocity)
{
    if (velocity != 0)
        keyState.insert(noteNumber);
    else
        keyState.remove(noteNumber);

    // Pass the full 128-slot array to the shader
    shader.setUniformData("keyState", keyState.asBuffer(true));
}

// Context: asBuffer(false) returns only occupied elements, ideal
// for iterating active notes without processing 128 empty slots.

const var pressedNotes = Engine.createUnorderedStack();

inline function analyzeChord()
{
    if (pressedNotes.size() < 3)
        return;

    // Iterate only the occupied elements
    local activeBuffer = pressedNotes.asBuffer(false);
    local pitchClasses = [];

    for (note in activeBuffer)
    {
        local pc = parseInt(note) % 12;
        pitchClasses.push(pc);
    }

    Console.print("Pitch classes: " + trace(pitchClasses));
}

const var us = Engine.createUnorderedStack();
us.insert(1.0);
us.insert(2.0);
us.insert(3.0);

// Copy to Array
var arr = [];
us.copyTo(arr);
Console.print(arr.length); // 3

// Copy to Buffer (must be strictly larger than stack size)
const var bf = Buffer.create(4);
us.copyTo(bf);
Console.print(bf[0]); // 1.0

// Context: A granular effect tracks active notes and randomly selects
// from them to spawn new grains. insert() provides set semantics
// (no duplicates), and bracket access picks a random element.

const var activeNotes = Engine.createUnorderedStack();

// onNoteOn / onNoteOff
inline function handleNote(noteNumber, velocity)
{
    if (velocity != 0)
        activeNotes.insert(noteNumber);
    else
        activeNotes.remove(noteNumber);
}

// Timer callback: pick a random held note for grain spawning
inline function spawnGrain()
{
    local count = activeNotes.size();

    if (count > 0)
    {
        // Bracket access reads from the float array by index
        local randomNote = activeNotes[Math.randInt(0, count)];
        Console.print("Spawning grain at note: " + randomNote);
    }
}

// Context: Inserting events requires a MessageHolder. The current
// MIDI event is captured with Message.store(), then the holder
// is passed to insert(). Duplicate detection uses the configured
// compare function.

const var eventStack = Engine.createUnorderedStack();
const var holder = Engine.createMessageHolder();
eventStack.setIsEventStack(true, eventStack.EventId);

// onNoteOn
inline function handleNoteOn()
{
    Message.store(holder);
    eventStack.insert(holder); // returns false if event ID already present
}

// Context: When a note-off arrives, removeIfEqual finds the matching
// note-on in the stack and writes the ORIGINAL event back into the holder.
// This preserves the note-on's velocity and timestamp, which may differ
// from the note-off's values.

const var noteStack = Engine.createUnorderedStack();
const var holder = Engine.createMessageHolder();
noteStack.setIsEventStack(true, noteStack.EventId);

reg uptimes = [];
uptimes.reserve(128);

// onNoteOn: push event and record timing
inline function onNoteOn()
{
    Message.store(holder);
    noteStack.insert(holder);
    uptimes[Message.getNoteNumber()] = Engine.getUptime();
}

// onNoteOff: pop matching event, compute held duration
inline function onNoteOff()
{
    Message.store(holder);

    // After this call, holder contains the original note-on event
    noteStack.removeIfEqual(holder);

    // Use the held duration to select short vs long release samples
    local duration = Engine.getUptime() - uptimes[holder.getNoteNumber()];
    local useShortRelease = duration < 0.8;

    // The holder's velocity comes from the original note-on,
    // not the note-off - important for release sample gain scaling
    Synth.addMessageFromHolder(holder);
}

// Context: A release sample player tracks note-on events so that when
// a note-off arrives, it can recover the original event's metadata
// (velocity, timestamp) to trigger an appropriate release sample.

const var noteStack = Engine.createUnorderedStack();
const var holder = Engine.createMessageHolder();

// Configure as event stack with EventId matching (pairs note-on/off)
noteStack.setIsEventStack(true, noteStack.EventId);

// In onNoteOn: store the current event and push it onto the stack
inline function handleNoteOn()
{
    Message.store(holder);
    noteStack.insert(holder);
}

// In onNoteOff: pop the matching note-on event from the stack
inline function handleNoteOff()
{
    Message.store(holder);

    // removeIfEqual finds the matching event by ID and writes
    // the original note-on data back into the holder
    noteStack.removeIfEqual(holder);

    // holder now contains the original note-on event - use its
    // velocity, timestamp, etc. for release sample selection
    Synth.addMessageFromHolder(holder);
}

// Context: When a sustain pedal is released, all events in the stack
// must be processed and removed. storeEvent reads without removing,
// then removeElement clears the slot. Draining from index 0 avoids
// the index-shifting problems of forward iteration with removal.

const var noteStack = Engine.createUnorderedStack();
const var holder = Engine.createMessageHolder();
const var processedNotes = Engine.createMidiList();
noteStack.setIsEventStack(true, noteStack.EventId);

inline function drainOnPedalOff()
{
    processedNotes.clear();

    while (!noteStack.isEmpty())
    {
        // Read the event at index 0 into the holder
        noteStack.storeEvent(0, holder);

        // Remove index 0 (last element swaps in, stack shrinks by 1)
        noteStack.removeElement(0);

        // Deduplicate: skip if this note number was already processed
        // (handles edge case of multiple events for the same pitch)
        if (processedNotes.getValue(holder.getNoteNumber()) == -1)
        {
            processedNotes.setValue(holder.getNoteNumber(), 1);
            Synth.addMessageFromHolder(holder);
        }
    }
}

