// Context: When a control switches which channel it displays (e.g., an XY pad
// that follows the selected channel), the automation callbacks need to be
// rebound. First remove old callbacks by passing an empty string, then
// attach new ones for the current channel's automation IDs.

const var uph = Engine.createUserPresetHandler();

// On channel switch: rebind the XY pad to the new channel's automation slots
inline function onChannelSwitch(panel, channelIndex)
{
    // Remove previous callbacks by passing a non-function value
    if (isDefined(panel.data.xId))
        uph.attachAutomationCallback(panel.data.xId, "", false);

    if (isDefined(panel.data.yId))
        uph.attachAutomationCallback(panel.data.yId, "", false);

    // Build new automation IDs for the selected channel
    panel.data.xId = "Mixer " + (channelIndex + 1) + " X";
    panel.data.yId = "Mixer " + (channelIndex + 1) + " Y";

    // Attach async callbacks that update the panel display
    uph.attachAutomationCallback(panel.data.xId, function [panel](index, value)
    {
        local v = panel.getValue();
        v[0] = value;
        panel.setValue(v);
        panel.repaint();
    }, AsyncNotification);

    uph.attachAutomationCallback(panel.data.yId, function [panel](index, value)
    {
        local v = panel.getValue();
        v[1] = value;
        panel.setValue(v);
        panel.repaint();
    }, AsyncNotification);

    // Read current values to initialize the display
    local allValues = uph.createObjectForAutomationValues();
    local xIdx = uph.getAutomationIndex(panel.data.xId);
    local yIdx = uph.getAutomationIndex(panel.data.yId);

    panel.setValue([allValues[xIdx].value, allValues[yIdx].value]);
    panel.repaint();
}

// Context: In a multi-channel instrument, copying a channel's settings to
// another channel requires capturing all automation values for the source
// channel, then applying them to the target. createObjectForAutomationValues()
// provides the full snapshot; the script filters and remaps by channel.

const var uph = Engine.createUserPresetHandler();

inline function copyChannel(sourceIndex, targetIndex)
{
    local allValues = uph.createObjectForAutomationValues();
    // allValues is: [{"id": "Gain A1", "value": -6.0}, {"id": "Pan A1", "value": 0.5}, ...]

    local sourceTag = " " + (sourceIndex + 1);
    local targetTag = " " + (targetIndex + 1);

    for (slot in allValues)
    {
        // Find slots belonging to the source channel
        if (slot.id.indexOf(sourceTag) != -1)
        {
            // Remap the ID to the target channel
            local targetId = slot.id.replace(sourceTag, targetTag);
            local targetIdx = uph.getAutomationIndex(targetId);

            if (targetIdx >= 0)
                uph.setAutomationValue(targetIdx, slot.value);
        }
    }
}

// Context: Some operations (like cleaning up unused data) should not run
// immediately after a preset load because the load process may still be
// settling state. Use getSecondsSinceLastPresetLoad() as a debounce guard
// to skip the operation if a preset was loaded very recently.

const var uph = Engine.createUserPresetHandler();

inline function cleanupUnusedData(obj)
{
    // Skip cleanup if a preset was loaded less than 500ms ago
    local elapsed = uph.getSecondsSinceLastPresetLoad();

    if (elapsed < 0.5)
    {
        Console.print("Skipping cleanup - preset loaded " +
                       parseInt(elapsed * 1000) + "ms ago");
        return;
    }

    // Safe to proceed with cleanup
    // ...
}

// Call from a timer callback or button handler
cleanupUnusedData({});

// Context: A "preset lock" feature preserves certain parameter values when
// the user manually changes presets, but allows DAW session recall to
// overwrite everything. isInternalPresetLoad() distinguishes these two cases.

const var uph = Engine.createUserPresetHandler();

// Assume lockButton and mixKnob are ScriptButton/ScriptSlider references
reg lockValue;

// In the post-callback: restore locked value only for user-initiated loads
uph.setPostCallback(function(presetFile)
{
    local isUserLoad = !uph.isInternalPresetLoad();
    local lockEnabled = lockButton.getValue();

    if (isUserLoad && lockEnabled && isDefined(lockValue))
    {
        // Restore the locked parameter to its pre-load value
        mixKnob.setValue(lockValue);
        mixKnob.changed();
    }
    else
    {
        // Capture the new value for future locking
        lockValue = mixKnob.getValue();
    }
});

const var uph = Engine.createUserPresetHandler();
uph.setEnableUserPresetPreprocessing(true, false);

uph.setPreCallback(function(presetData)
{
    local version = presetData.version;

    if (uph.isOldVersion(version))
    {
        // Migrate preset data from an older format
        Console.print("Migrating preset from version " + version);
    }
});

// Context: For a DAW to correctly record automation, parameter changes must
// be bracketed by begin/end gesture messages. When a custom ScriptPanel
// control (like an XY pad) is dragged, send gesture begin on mouseDown
// and gesture end on mouseUp.

const var uph = Engine.createUserPresetHandler();
const var CUSTOM_AUTOMATION = 1; // automationType for CustomAutomation slots

// Assume xyPad is a ScriptPanel with data.xIndex and data.yIndex
// set to the automation slot indices for its X and Y parameters
xyPad.setMouseCallback(function(event)
{
    if (event.clicked && !event.drag && !event.rightClick)
    {
        // Begin gesture for both X and Y parameters
        uph.sendParameterGesture(CUSTOM_AUTOMATION, this.data.xIndex, true);
        uph.sendParameterGesture(CUSTOM_AUTOMATION, this.data.yIndex, true);
    }

    if (event.mouseUp && !event.rightClick)
    {
        // End gesture for both parameters
        uph.sendParameterGesture(CUSTOM_AUTOMATION, this.data.xIndex, false);
        uph.sendParameterGesture(CUSTOM_AUTOMATION, this.data.yIndex, false);
    }

    if (event.drag)
    {
        // Update values between gesture begin/end
        local area = this.getLocalBounds(0);
        local normX = Math.range((event.x - area[0]) / area[2], 0.0, 1.0);
        local normY = Math.range((event.y - area[1]) / area[3], 0.0, 1.0);

        uph.setAutomationValue(this.data.xIndex, normX);
        uph.setAutomationValue(this.data.yIndex, normY);
    }
});

// Context: A ScriptPanel acting as an XY pad uses setAutomationValue
// to push its position into the automation system. This routes the
// values through all connections (processor parameters, cables, meta
// connections) and notifies any attached callbacks.

const var uph = Engine.createUserPresetHandler();

// Cache automation indices at init time for performance.
// These IDs must match slots registered via setCustomAutomation.
const var xIndex = uph.getAutomationIndex("Mixer 1 X");
const var yIndex = uph.getAutomationIndex("Mixer 1 Y");

inline function onPadChange(component, value)
{
    // value is a 2-element array [x, y] from the XY pad
    uph.setAutomationValue(xIndex, value[0]);
    uph.setAutomationValue(yIndex, value[1]);
}

// Reset to center position
inline function resetPad()
{
    uph.setAutomationValue(xIndex, 0.5);
    uph.setAutomationValue(yIndex, 0.0);
}

