// Context: When a plugin update changes data formats (e.g., replacing an
// AudioWaveform with a Sampler-based sample importer), preprocessing with
// shouldUnpackComplexData=true allows the pre-callback to inspect and
// transform Base64-encoded data inside the preset.

const var uph = Engine.createUserPresetHandler();

// Enable preprocessing with complex data unpacking
// - true: pre-callback receives JSON instead of a File
// - true: Base64 data and JSON-encoded strings are decoded
uph.setEnableUserPresetPreprocessing(true, true);

uph.setPreCallback(function(data)
{
    // data.Content is an array of component value objects
    for (c in data.Content)
    {
        if (c.id == "OldWaveform")
        {
            // c.data is now the decoded Base64 content (not a raw string)
            // Transform it into the new format and inject a replacement entry
            var newEntry = {
                "type": "ScriptPanel",
                "id": "SampleDropper",
                "value": {
                    "isCustom": true,
                    "value": c.data
                }
            };

            data.Content.push(newEntry);
            break;
        }
    }
});

// Context: The most common use case: inspect the preset version and
// add/rename/remap simple control values. Complex data unpacking is
// not needed when you only work with scalar values.

const var uph = Engine.createUserPresetHandler();

// Enable preprocessing but skip complex data unpacking (faster)
uph.setEnableUserPresetPreprocessing(true, false);

uph.setPreCallback(function(presetData)
{
    if (uph.isOldVersion(presetData.version))
    {
        // Add controls that were introduced in newer versions
        presetData.Content.push({
            "type": "ScriptButton",
            "id": "btnNewFeature",
            "value": true
        });

        // Remap a renamed control
        for (c in presetData.Content)
        {
            if (c.id == "knbOldGate")
            {
                c.id = "knbGateHold";
                c.value = Math.max(c.value, 10);
                break;
            }
        }
    }
});

// Context: When a DAW records automation, abrupt parameter changes can cause
// audible artifacts. The gesture callback detects when the DAW (or script)
// begins/ends a parameter interaction, allowing the plugin to enable
// parameter smoothing during the gesture and disable it afterward.

const var uph = Engine.createUserPresetHandler();
const var CUSTOM_AUTOMATION = 1;

// Map automation indices to their smoothing processor and parameter
// (populated during init based on automation slot layout)
const var SMOOTHERS = {};

inline function onParameterGesture(type, index, isStart)
{
    if (type == CUSTOM_AUTOMATION)
    {
        local s = SMOOTHERS[index];

        if (isDefined(s))
        {
            // Enable/disable smoothing on the associated gain module
            s.module.setAttribute(s.parameterIndex, isStart);
        }
    }
};

uph.setParameterGestureCallback(onParameterGesture);

// Also send gestures from script-driven UI controls (e.g., knob mouse events)
// so the same smoothing logic applies to both DAW and manual interaction.
// Assume gainKnob is a ScriptSlider with an "automationID" custom property.
gainKnob.setMouseCallback(function(event)
{
    if (event.clicked || event.mouseUp)
    {
        local id = this.get("automationID");
        local index = uph.getAutomationIndex(id);
        onParameterGesture(CUSTOM_AUTOMATION, index, event.clicked);
    }
});

